/* ══════════ ALMANAC FOLLOW-UP TABLE (000-999, 2 relatives each) ══════════
   Packed as 6 chars per key, indexed by the number itself.
   Transcribed from the 2016 almanac pages. Rows 021 / 057 / 171 unconfirmed. */
const PACKED = "";
const ALMANAC = {};                 // '000' -> ['799','954']
const REVERSE = {};                 // '799' -> ['000', ...]  (who points at me)
for (let i = 0; i < 1000; i++) {
  const k = String(i).padStart(3, '0');
  const a = PACKED.substr(i * 6, 3), b = PACKED.substr(i * 6 + 3, 3);
  ALMANAC[k] = [a, b];
  (REVERSE[a] = REVERSE[a] || []).push(k);
  (REVERSE[b] = REVERSE[b] || []).push(k);
}
