/* ══════════ BOOK SELECTION ══════════
   Six checkboxes, any combination. The four core books are on by default;
   Grandma 2025 and Red Side (both tested at chance — see the state-matched
   scorecard, where every book keeps its own row whatever is ticked) are off.
   Whatever is ticked is what the watch lists, the convergence panel, the state
   view and State Specific Numbers use. The choice is remembered per browser. */
const BOOKS_KEY='almanac_books_v1';
const BOOK_DEFS=[
  {id:'16', el:'bk16', name:"Almanac '16"}, {id:'17', el:'bk17', name:"Almanac '17"},
  {id:'fu', el:'bkfu', name:'Follow Ups'},  {id:'rel',el:'bkrel',name:'Relative Numbers'},
  {id:'25', el:'bk25', name:'Grandma 2025'}, {id:'rs', el:'bkrs', name:'Red Side'} ];
const BOOKS_DEFAULT=['16','17','fu','rel','25','rs'];
function booksOn(){
  const on=new Set();
  BOOK_DEFS.forEach(b=>{ const e=document.getElementById(b.el);
    if(e && typeof e.checked==='boolean' ? e.checked : BOOKS_DEFAULT.indexOf(b.id)>=0) on.add(b.id); });
  return on;
}
const bookNames = () => BOOK_DEFS.filter(b=>booksOn().has(b.id)).map(b=>b.name);
function booksChanged(){
  try{ localStorage.setItem(BOOKS_KEY, JSON.stringify([...booksOn()])); }catch(e){}
  if(typeof SN_CACHE!=='undefined') SN_CACHE=null;
  render();
}
/* Marcus wants every book ticked each time the dashboard opens, so the page starts
   from all six rather than whatever was ticked last visit; unticking still works
   for the rest of that visit. */
function restoreBooks(){
  BOOK_DEFS.forEach(b=>{ const e=document.getElementById(b.el); if(e) e.checked=BOOKS_DEFAULT.indexOf(b.id)>=0; });
}
/* the two-relative almanac-shaped books feed the relatives lists at the top */
