/* ══════════ SHARED HELPERS ══════════ */
const sortD   = s => s.split('').sort().join('');
const mirrorOf= s => s.split('').map(d => (+d + 5) % 10).join('');
const perms   = s => [...new Set([s[0]+s[1]+s[2], s[0]+s[2]+s[1], s[1]+s[0]+s[2],
                                  s[1]+s[2]+s[0], s[2]+s[0]+s[1], s[2]+s[1]+s[0]])];
const isTriple  = n => n[0] === n[1] && n[1] === n[2];
const isHundred = n => { const s = sortD(n); return s[0] === '0' && s[1] === '0'; };
const SERIES_BOX = new Set(['012','123','234','345','456','567','678','789','890','901'].map(sortD));
const isSeries = n => SERIES_BOX.has(sortD(n));
/* added for the full rule sheet (rules 3, 7, 12-15, 23-26, 32-34) */
const isDouble   = n => n.length===3 && !isTriple(n) && (n[0]===n[1] || n[1]===n[2] || n[0]===n[2]);
/* false trip (Marcus's definition): a double plus the MIRROR of the doubled digit
   (mirror: 0-5, 1-6, 2-7, 3-8, 4-9) — 116 227 338 449 550 661 772 883 994 005, any order */
const isFalseTrip = n => { if(!isDouble(n)) return false; const s=sortD(n);
  const p = s[0]===s[1] ? s[0] : s[1], o = s[0]===s[1] ? s[2] : s[0];
  return (+p + 5) % 10 === +o; };
const digitSum = n => n.split('').reduce((a,d)=>a + +d, 0);
const allOdd   = n => n.split('').every(d => (+d)%2===1);
const isTrip4  = n => n.length===4 && Object.values(n.split('').reduce((m,d)=>(m[d]=(m[d]||0)+1,m),{})).some(k=>k>=3);
const SERIES4 = new Set(['0123','1234','2345','3456','4567','5678','6789','0789','0189','0129']);
const isSeries4 = n => n.length===4 && SERIES4.has(sortD(n));
const containsDigits = (n, need) => { const a=n.split(''); return need.split('').every(d => { const i=a.indexOf(d); if(i<0) return false; a.splice(i,1); return true; }); };

/* ══════════ SERIES-BRINGS TABLE ══════════
   Each series (boxed) 'brings' four doubles. Direction matters for priming:
   a brought-double landing BEFORE its series is what flags the series as primed.
   All matching is boxed — 234 and 342 are the same series; 882 and 828 the same double.
   Source: user photo IMG_7945. The 456 row's self-entry was a transcription error and is dropped. */
const SERIES_BRINGS_RAW = {
  '123': ['882','338','688','933'],
  '234': ['844','336','445','667'],
  '345': ['009','552','300','388'],
  '456': ['114','611','199'],
  '567': ['112','110','559','966'],
  '678': ['668','220','117','588'],
  '789': ['227','223','889','665'],
  '890': ['114','661','553','002'],
  '901': ['755','877','009','338']
};
// Boxed form: series-box -> array of brought-double boxes
const SERIES_BRINGS = {};
Object.entries(SERIES_BRINGS_RAW).forEach(([ser, dbls]) => {
  SERIES_BRINGS[sortD(ser)] = { series: ser, dbls, dblBox: dbls.map(sortD) };
});
// Reverse: which series does this double (boxed) belong to?
const DOUBLE_TO_SERIES = {};
Object.values(SERIES_BRINGS).forEach(e => {
  e.dblBox.forEach((db, i) => {
    (DOUBLE_TO_SERIES[db] = DOUBLE_TO_SERIES[db] || []).push({ series: e.series, double: e.dbls[i] });
  });
});
const boxMode = () => document.getElementById('boxMode').checked;
const keyOf = n => boxMode() ? sortD(n) : n;
const lookback = () => parseInt(document.getElementById('lookback').value, 10) || 1;

/* Pool the last k logged days. Returns the flat draw list plus, for each
   box-key, where and how long ago it landed. */
function pooledDays(k, endIdx){
  const v = DB.dayLog.filter(e => e.dayStates);
  const end = (endIdx === undefined) ? v.length : endIdx + 1;
  const slice = v.slice(Math.max(0, end - k), end);
  const draws = [], where = {};
  slice.forEach((day, i) => {
    const ago = slice.length - 1 - i;
    Object.entries(day.dayStates).forEach(([c, ns]) => ns.forEach(n => {
      draws.push(n);
      const kk = keyOf(n);
      (where[kk] = where[kk] || []).push({ num:n, state:c, ago });
    }));
  });
  return { draws, where, days: slice.length };
}
function agoTxt(a){ return a === 0 ? 'today' : a === 1 ? 'yesterday' : a + 'd ago'; }
function siteTxt(list){
  if(!list || !list.length) return '';
  const best = list.slice().sort((x,y) => x.ago - y.ago);
  const head = best.slice(0,2).map(e => nm(e.state) + ' ' + agoTxt(e.ago)).join(', ');
  return head + (best.length > 2 ? ' +' + (best.length-2) : '');
}

/* +246 rundown — the whole second book is this one formula */
function rundown246(n) {
  const out = []; let v = parseInt(n, 10);
  for (let i = 0; i < 5; i++) { v = (v + 246) % 1000; out.push(String(v).padStart(3, '0')); }
  return out;
}
function shiftSet(n, set) {
  const d = n.split('').map(Number), r = new Set();
  for (const a of set) for (const b of set) for (const c of set)
    r.add(d.map((x, i) => (x + [a,b,c][i]) % 10).join(''));
  return [...r];
}

