const STATE_NAMES = {az:'Arizona',ar:'Arkansas',ca:'California',co:'Colorado',ct:'Connecticut',
 de:'Delaware',fl:'Florida',ga:'Georgia',id:'Idaho',il:'Illinois',in:'Indiana',ia:'Iowa',
 ks:'Kansas',ky:'Kentucky',la:'Louisiana',md:'Maryland',mi:'Michigan',mn:'Minnesota',
 ms:'Mississippi',mo:'Missouri',ne:'Nebraska',nj:'New Jersey',nm:'New Mexico',ny:'New York',
 nc:'North Carolina',oh:'Ohio',ok:'Oklahoma',on:'Ontario',pa:'Pennsylvania',pr:'Puerto Rico',
 qc:'Quebec',sc:'South Carolina',tn:'Tennessee',tx:'Texas',xx:'Tri-State',va:'Virginia',
 wa:'Washington',dc:'Washington DC',wv:'West Virginia',wc:'Western Canada',wi:'Wisconsin',
 /* Pick-4-only jurisdictions: these run no Pick 3 in the daily results post, so
    they never appeared in the three-digit history — they are here for Pick 4. */
 ac:'Atlantic Canada',ma:'Massachusetts',or:'Oregon',ri:'Rhode Island',
 /* Caribbean Lottery (Anguilla, Antigua, St Kitts, St Maarten, USVI): four Pick 3 and
    four Pick 4 draws a day — Morning, Midday, Sunset, Evening. */
 cr:'Caribbean'};
const nm = c => STATE_NAMES[c] || c.toUpperCase();
function load(){ try{ const s=localStorage.getItem(KEY); if(s) DB=JSON.parse(s);}catch(e){}
  if(!DB.dayLog) DB.dayLog=[]; if(!DB.snaps) DB.snaps=[]; if(!DB.p4log) DB.p4log=[]; }
function save(){ DB_REV++; if(VIEW_ACTIVE) return; try{ localStorage.setItem(KEY, JSON.stringify(DB)); }catch(e){} }
/* Backtests walk the whole log, which is a year long now that the feed backfills.
   Keep each result until the data (every change goes through save) or a setting
   it reads changes, so a redraw doesn't re-run them and freeze the page. */
let DB_REV = 0; const HIST_MEMO = {};
function histMemo(name, fn){
  const key = [DB_REV, DB.dayLog.length, (VIEW_ACTIVE && VIEW) ? VIEW.day : '', [...booksOn()].sort().join(),
    boxMode(), lookback(), document.getElementById('topN').value].join('|');
  const m = HIST_MEMO[name];
  if(m && m.key === key && m.db === DB) return m.val;
  const val = fn(); HIST_MEMO[name] = { key, db: DB, val }; return val;
}
/* Export as a real file on the hosted page (the browser download link is
   blocked inside the frame). The button appears only once the viewer's
   app says it can save files; Copy backup stays as the path that works
   everywhere. */
let DL=null;
(async()=>{ try{ if(window.claude && claude.use){ DL=await claude.use('downloads');
  if(DL){ const b=document.getElementById('exportBtn'); if(b) b.style.display=''; } } }catch(e){} })();
async function exportFile(){
  const st=document.getElementById('bfStatus');
  if(!DL){ copyBackup(); return; }
  const name='almanac_convergence_'+todayISO()+'.json';
  try{ await DL.save({filename:name, data:JSON.stringify(DB)});
    if(st){ st.className='status ok'; st.textContent='saved '+name+' \u2014 '+DB.dayLog.length+' days'; } }
  catch(e){ if(st){ st.className='status warn';
    st.textContent = e && e.code==='declined' ? 'export cancelled' : 'could not save a file here \u2014 use Copy backup instead'; } }
}

/* ══════════ PARSING ══════════ */
const chunkN = (d,w) => { const o=[]; for(let i=0;i+w<=d.length;i+=w) o.push(d.slice(i,i+w)); return o; };
const chunk3 = d => chunkN(d,3);
/* Same state-splitting for Pick 3 (w=3) and Pick 4 (w=4), so both boxes read
   the identical results format. */
function parseDayBlocks(text, w){
  w = w || 3;
  const chunkW = d => chunkN(d, w);
  /* Both paste formats are reduced to the same |code| marker stream, in
     document order, and read in ONE pass.
     Two fixes live here, both found in real pastes:
     (1) The old code took the linked format OR the plain-name format, never
         both — a copy covering several days often mixes them, and whichever
         came second was silently dropped.
     (2) The old link pattern read digits with \d*, which stops at a newline,
         so a state posting a third or fourth draw on its own line (Georgia,
         Tennessee, Texas, DC, Oregon) lost everything after the first line.
         Whitespace is now collapsed before the digits are chunked. */
  let work = ' ' + text.replace(/\s+/g,' ') + ' ';
  /* linked form: [Anything](…/past/xx?…) → |xx| */
  work = work.replace(/\[[^\]]*\]\s*\(\s*[^)]*\/past\/([a-z]{2,3})\?[^)]*\)/gi,
    (mm,c)=>'|'+c.toLowerCase()+'|');
  /* any bare link left over */
  work = work.replace(/https?:\/\/[^\s)]*\/past\/([a-z]{2,3})\?[^\s)]*\)?/gi,
    (mm,c)=>'|'+c.toLowerCase()+'|');
  /* AUDIT FIX: the results post spells "Québec" with an accent, which never
     matched the ASCII name — so Québec's draw was silently appended to the
     previous state's chunk (Puerto Rico on weekdays, Pennsylvania on Sundays).
     22 days of history carried that contamination. Strip accents first. */
  work = work.normalize('NFD').replace(/[̀-ͯ]/g,'');
  const pairs = Object.entries(STATE_NAMES).map(([c,n])=>[c,n]);
  [['dc','Washington, D.C.'],['dc','Washington D.C.'],['dc','Washington DC'],
   ['xx','Tri-State (ME, NH & VT)'],['xx','Tri-State'],['qc','Quebec'],
   ['cr','U.S. Virgin Islands'],['cr','Caribbean CAR']].forEach(p=>pairs.push(p));
  pairs.sort((a,b)=>b[1].length-a[1].length);
  pairs.forEach(([c,name])=>{ work = work.replace(
    new RegExp(name.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi'), '|'+c+'|'); });
  const parts = work.split('|');
  const seq=[];
  for(let i=0;i<parts.length-1;i++){
    const c = parts[i].trim().toLowerCase();
    if(STATE_NAMES[c]){ const n=chunkW(parts[i+1].replace(/\D/g,'')); if(n.length) seq.push([c,n]); }
  }
  const days=[]; let cur={};
  seq.forEach(([c,n])=>{ if(cur[c]){ days.push(cur); cur={}; } cur[c]=n; });
  if(Object.keys(cur).length) days.push(cur);
  return days;
}

/* ══════════ ADD / UNDO / BACKUP ══════════ */
const daySig = p => Object.keys(p).sort().map(c=>c+':'+p[c].join(',')).join('|');
function addParsedDay(parsed, dateStr){
  const codes = Object.keys(parsed); if(!codes.length) return 'empty';
  /* AUTO FEED: a paste for a date the log already holds is a fix, not a new day.
     It replaces just those states on that date and marks them as yours, so the
     automatic feed never overwrites them afterwards. */
  const ex = dateStr ? DB.dayLog.find(e => e.date === dateStr) : null;
  if(ex){
    ex.manualStates = ex.manualStates || []; ex.autoStates = ex.autoStates || [];
    codes.forEach(c => { ex.dayStates[c] = parsed[c].slice();
      if(ex.manualStates.indexOf(c) < 0) ex.manualStates.push(c);
      ex.autoStates = ex.autoStates.filter(x => x !== c); });
    refreshDay(ex); rebuildByState(); DB.lastBatch = null;
    return 'merged';
  }
  const sig = daySig(parsed), last = DB.dayLog[DB.dayLog.length-1];
  if(last && last.sig === sig && !armed('dupday',
      'That is identical to the day already at the end of your log. Press Add day again to add it anyway.'))
    return 'skipped';
  const batch = {};
  codes.forEach(c=>{
    if(!DB.byState[c]) DB.byState[c]=[];
    const dn = parsed[c].slice().reverse();
    DB.byState[c] = [...dn, ...DB.byState[c]];
    if(DB.byState[c].length > 600) DB.byState[c].length = 600;
    batch[c] = dn.length;
  });
  const flat=[]; Object.values(parsed).forEach(ns=>ns.forEach(n=>flat.push(n)));
  DB.days++; DB.lastBatch = batch;
  /* date stamp: lets the Vibrations panel place a daily vibration on its own
     date and scope the month-long lists. Days logged before this existed
     simply carry no date and are handled as such. */
  DB.dayLog.push({ sig, date: dateStr || yesterdayISO(), draws: flat, dayStates: parsed,
                   appeared: [...appearedPairs(parsed)] });
  return 'added';
}
function addDay(){
  const st = document.getElementById('parseStatus');
  const blocks = parseDayBlocks(document.getElementById('pasteBox').value);
  if(!blocks.length){ st.className='status warn';
    st.textContent='No states found. Paste the full results post.'; return; }
  /* The draw date is the date the numbers were DRAWN, not the day you paste them.
     Defaults to yesterday, because results are normally pasted the next morning.
     A multi-day paste is dated consecutively, ending on that date. */
  const endDate = document.getElementById('drawDate').value || yesterdayISO();
  /* A date can only be logged once. Two days carrying the same date would both
     mark the Vibrations page for that date and skew every dated count. */
  const have=new Set(DB.dayLog.map(e=>e.date).filter(Boolean));
  const clash=blocks.map((b,i)=>isoAdd(endDate, -(blocks.length-1-i))).filter(d=>have.has(d));
  if(clash.length && !armed('dupdate','Your log already has '+clash.join(', ')+
      ' (the automatic results may have filled it). Press Add day again to fix that day with your paste: '+
      'the states you pasted replace what is there and stay yours.')) return;
  let added=0, skipped=0, draws=0, merged=0;
  blocks.forEach((b,i)=>{ const r=addParsedDay(b, isoAdd(endDate, -(blocks.length-1-i)));
    if(r==='added'){ added++; Object.values(b).forEach(n=>draws+=n.length); }
    else if(r==='merged'){ merged++; Object.values(b).forEach(n=>draws+=n.length); }
    else if(r==='skipped') skipped++; });
  save();
  st.className='status ok';
  st.textContent = (added || !merged ? added+' day'+(added!==1?'s':'')+', '+draws+' draws' : '')+
    (added?' dated '+(blocks.length>1
      ? isoAdd(endDate,-(blocks.length-1))+' to '+endDate : endDate)+' · ':' ')+
    (merged?merged+' day'+(merged>1?'s':'')+' fixed with your paste · ':'')+
    (skipped?' ('+skipped+' duplicate skipped)':'')+' · '+DB.days+' total';
  document.getElementById('pasteBox').value='';
  render();
}
function undoLast(){
  if(!DB.lastBatch) return;
  Object.entries(DB.lastBatch).forEach(([c,n])=>{ if(DB.byState[c]) DB.byState[c].splice(0,n); });
  DB.lastBatch=null; if(DB.days>0) DB.days--; if(DB.dayLog.length) DB.dayLog.pop();
  if(DB.snaps) DB.snaps = DB.snaps.filter(sn => sn.at <= DB.dayLog.length);
  save(); render();
}
function clearAll(){
  if(!armed('clearall','This erases every logged day. Press Clear all again to confirm.')) return;
  DB={byState:{},days:0,lastBatch:null,dayLog:[]}; save(); render();
}
/* Downloads are blocked inside a hosted page, so this puts the whole backup on
   the clipboard and also drops it in a box you can select by hand if the
   clipboard is refused. Paste it into a text file to keep it. */
function copyBackup(){
  const txt = JSON.stringify(DB);
  const out = document.getElementById('backupOut');
  const show = msg => { out.innerHTML =
    '<div class="baseline" style="margin-top:10px"><b>'+msg+'</b> '+
    'Paste it into a plain text file and save it as <code>almanac_convergence.json</code>. '+
    'To restore it later, press Import and pick that file.</div>'+
    '<textarea rows="3" onclick="this.select()" readonly>'+txt+'</textarea>'; };
  try{
    navigator.clipboard.writeText(txt)
      .then(()=>show('Copied &mdash; '+DB.dayLog.length+' logged days are on your clipboard.'))
      .catch(()=>show('Could not reach the clipboard, so here it is &mdash; click the box and copy it.'));
  }catch(e){ show('Could not reach the clipboard, so here it is &mdash; click the box and copy it.'); }
}
/* No exportHistory() here: a hosted page cannot hand the viewer a file, so the
   backup path is Copy backup, which works everywhere. */
function importHistory(e){
  const f=e.target.files[0]; if(!f) return; const r=new FileReader();
  r.onload=()=>{ try{ DB=JSON.parse(r.result); if(!DB.dayLog) DB.dayLog=[]; save(); render(); }
                 catch(err){ const s=document.getElementById('bfStatus');
                   if(s){ s.className='status warn'; s.textContent='that file could not be read'; } } };
  r.readAsText(f);
}
function copyNum(n){ if(navigator.clipboard) navigator.clipboard.writeText(n); }

/* ══════════ PAIRS ══════════ */
const ALL_PAIRS = (()=>{ const a=[]; for(let i=0;i<10;i++) for(let j=i;j<10;j++) a.push(''+i+j); return a; })();
function pairsOfNum(n){ const s=new Set(); const add=(a,b)=>s.add(a<=b?a+b:b+a);
  add(n[0],n[1]); add(n[1],n[2]); add(n[0],n[2]); return s; }
function appearedPairs(parsed){ const seen=new Set();
  Object.values(parsed).forEach(ns=>ns.forEach(n=>pairsOfNum(n).forEach(p=>seen.add(p)))); return seen; }

/* ══════════ ALMANAC ANALYSIS ══════════
   Three states, in descending order of how selective they are:
     confirmed — both relatives of K landed, K itself did not  → watch K
     partial   — K landed and one of its relatives landed      → watch the other
     watch     — K landed                                      → watch both relatives  */
function almanacAnalysis(pool, onlyBooks){
  const where = pool.where;
  const fell = n => !!where[keyOf(n)];
  const at   = n => where[keyOf(n)] || null;
  const books = onlyBooks || activeBooks();

  // Each book is evaluated on its own terms; a key can be flagged by one book,
  // the other, or both. The `books` array on each row records which.
  const cMap = new Map(), pMap = new Map(), wMap = new Map();
  const push = (map, k, entry, book) => {
    if(map.has(k)){ const e = map.get(k); e.books.push(book); e.alt.push(entry); }
    else map.set(k, Object.assign({ key:k, books:[book], alt:[] }, entry));
  };
  books.forEach(bk => {
    const T = bookTable(bk);
    for (let i = 0; i < 1000; i++) {
      const k = String(i).padStart(3,'0');
      const [a,b] = T[k];
      const kf = fell(k), af = fell(a), bf = fell(b);
      const src = [at(a), at(b)];
      if (af && bf && !kf)       push(cMap, k, { rel:[a,b], hit:[true,true], src }, bk);
      else if (kf && (af ^ bf))  push(pMap, k, { rel:[a,b], hit:[af,bf], src, want: af ? b : a }, bk);
      else if (kf && !af && !bf) push(wMap, k, { rel:[a,b], hit:[false,false], src:[null,null] }, bk);
    }
  });
  // rows flagged by both books sort first — two opinions pointing the same way
  const byBooks = (x,y) => y.books.length - x.books.length || x.key.localeCompare(y.key);
  const confirmed = [...cMap.values()].sort(byBooks);
  const partial   = [...pMap.values()].sort(byBooks);
  const watch     = [...wMap.values()].sort(byBooks);
  // coverage: how much of the 1000-number field is currently flagged
  const flagged = new Set();
  confirmed.forEach(c => flagged.add(c.key));
  partial.forEach(p => flagged.add(p.want));
  watch.forEach(w => { flagged.add(w.rel[0]); flagged.add(w.rel[1]);
    w.alt.forEach(x => { flagged.add(x.rel[0]); flagged.add(x.rel[1]); }); });
  partial.forEach(p => p.alt.forEach(x => flagged.add(x.want)));
  return { confirmed, partial, watch, flagged };
}

/* ══════════ SERIES PRIMING ══════════
   For each series, find its brought-doubles that landed, and WHEN (ago).
   Direction rule: the double must lead — land at least as recently-or-earlier
   as the series' own last appearance (or the series hasn't shown at all in window).
   A primed series = doubles are in, series hasn't followed yet -> watch the series. */
function seriesAnalysis(pool){
  const where = pool.where;                 // box-key -> [{num,state,ago}]
  const at = bk => where[bk] || null;
  const minAgo = list => list ? Math.min(...list.map(e => e.ago)) : Infinity;

  /* Full-history lookup: when did this box-key last land, counting back over
     every logged day (not just the lookback window)? Returns days-ago + where. */
  function lastDrop(boxKey){
    const log = DB.dayLog || [];
    for(let i = log.length - 1; i >= 0; i--){
      const hits = (log[i].draws || []).filter(n => sortD(n) === boxKey);
      if(hits.length){
        const st = [];
        Object.entries(log[i].dayStates || {}).forEach(([c, ns]) =>
          ns.forEach(n => { if(sortD(n) === boxKey) st.push({ num:n, state:c }); }));
        return { ago: log.length - 1 - i, nums:[...new Set(hits)], states:st };
      }
    }
    return null;
  }

  const dropped = [], primed = [], dormant = [];
  Object.values(SERIES_BRINGS).forEach(e => {
    const serBox = sortD(e.series);
    const drop = lastDrop(serBox);              // null = never in the log

    /* THE RESET: once a series drops, its count starts over. Only doubles that
       landed AFTER the drop count toward priming it again — a double that led
       the previous appearance is spent, not evidence for the next one. */
    const cutoff = drop ? drop.ago : Infinity;  // days-ago of the last drop
    const led = [];
    e.dblBox.forEach((db, i) => {
      const hits = at(db);
      if(!hits) return;
      const fresh = hits.filter(h => h.ago < cutoff);   // strictly since the drop
      if(fresh.length)
        led.push({ double: e.dbls[i], ago: Math.min(...fresh.map(h=>h.ago)),
                   where: fresh, box: db });
    });

    const row = { series: e.series, serBox, ledBy: led, count: led.length,
                  drop, sinceDrop: drop ? drop.ago : null,
                  totalDays: (DB.dayLog||[]).length };

    if(drop && drop.ago === 0)      dropped.push(row);   // landed today -> reset point
    else if(led.length)             primed.push(row);    // rebuilding since the drop
    else                            dormant.push(row);   // nothing since the drop
  });
  dropped.sort((a,b) => a.series < b.series ? -1 : 1);
  primed.sort((a,b) => b.count - a.count || (b.sinceDrop||99) - (a.sinceDrop||99));
  dormant.sort((a,b) => (b.sinceDrop === null ? 999 : b.sinceDrop) -
                        (a.sinceDrop === null ? 999 : a.sinceDrop));
  return { dropped, primed, dormant, active: dropped };
}

/* ══════════ SHORTLIST SCORING ══════════ */
function scoreBoard(pool, an){
  const draws = pool.draws;
  const S = new Map();
  const bump = (n, w, why) => {
    if(!/^\d{3}$/.test(n)) return;
    if(!S.has(n)) S.set(n, { score:0, why:new Set() });
    const e = S.get(n); e.score += w; e.why.add(why);
  };
  // almanac, weighted by how selective each state is
  an.confirmed.forEach(c => bump(c.key, 10, 'both relatives'));
  an.partial.forEach(p => bump(p.want, 4, 'one relative'));
  an.watch.forEach(w => { bump(w.rel[0], 1, 'almanac'); bump(w.rel[1], 1, 'almanac'); });
  // classic methods, run off the most recent draw in each state
  const recent = [...new Set(draws)].slice(0, 40);
  recent.forEach(n => {
    rundown246(n).forEach(x => bump(x, 1, '+246'));
    [mirrorOf(n), ...perms(mirrorOf(n))].forEach(x => bump(x, 1, 'mirror'));
    shiftSet(n, [1,2,3]).forEach(x => bump(x, 0.5, 'shift'));
  });
  const fellKeys = new Set(draws.map(keyOf));
  return [...S.entries()]
    .map(([num,v]) => ({ num, score:v.score, why:[...v.why], fell: fellKeys.has(keyOf(num)) }))
    .sort((a,b) => b.score - a.score || a.num.localeCompare(b.num));
}

/* ══════════ HEAT: convergence tiering ══════════
   Counts how many DISTINCT signal types point at each number, plus how many
   separate sources fired within each type (e.g. two different states each
   dropping a relative). "Most relatives" -> highest tier. */
function heatScore(pool, an){
  const H = new Map();
  const touch = (n) => { if(!H.has(n)) H.set(n,{num:n,types:new Set(),sources:0,detail:[]}); return H.get(n); };
  const add = (n, type, count, label) => {
    if(!/^\d{3}$/.test(n)) return;
    const e = touch(n); e.types.add(type); e.sources += count;
    e.detail.push(label);
  };
  // almanac — the core of what the user means by "relatives"
  an.confirmed.forEach(c => {
    const src = (c.src[0]?c.src[0].length:0) + (c.src[1]?c.src[1].length:0);
    add(c.key, 'both', Math.max(2, src), 'both relatives ('+src+' sources)');
    if(c.books && c.books.length > 1) add(c.key, 'twobook', 1, 'flagged by both editions');
  });
  an.partial.forEach(pn => {
    const s0 = pn.src[0]?pn.src[0].length:0, s1 = pn.src[1]?pn.src[1].length:0;
    add(pn.want, 'one', Math.max(1, s0+s1), 'one relative');
  });
  an.watch.forEach(w => { add(w.rel[0],'watch',1,'almanac watch'); add(w.rel[1],'watch',1,'almanac watch'); });
  /* Follow Ups and Relative Numbers as their own signal types, so a number pointed
     at by all four books outranks one pointed at by two. Measured: 4-book top-6 ran
     at lift 1.80 on the first four days, but 6% of random-book sets beat that, so
     this is a ranking change under test — not an established improvement. */
  if(useFU()) pool.draws.forEach(n => {
    const t = FOLLOWUPS[n];
    if(t) add(t, 'followup', 1, 'Follow Ups: '+n+' &rarr; '+t);
  });
  if(useREL()) pool.draws.forEach(n => {
    const t = RELATIVES[sortD(n)];
    if(t) add(t, 'relative', 1, 'Relatives: '+sortD(n)+' &rarr; '+t);
  });
  /* the two lookup-only books, when ticked: one signal type each, own badge letter */
  if(use25()) pool.draws.forEach(n => {
    (ALMANAC25[n]||[]).forEach(t => add(t, 'g25', 1, 'Grandma 2025: '+n+' &rarr; '+t));
  });
  if(useRS()) pool.draws.forEach(n => {
    (BOLD_REL[sortD(n)]||[]).forEach(t => add(t, 'redside', 1, 'Red Side: '+sortD(n)+' &rarr; '+t));
  });
  // series priming — a primed series counts toward heat, weighted by how many doubles led it
  const sA = seriesAnalysis(pool);
  sA.primed.forEach(e => add(e.series, 'series', Math.max(1, e.count), 'series primed '+e.count+'/4'));

  // classic methods
  const recent = [...new Set(pool.draws)].slice(0, 60);
  recent.forEach(n => {
    rundown246(n).forEach(x => add(x,'r246',1,'+246'));
    [mirrorOf(n), ...perms(mirrorOf(n))].forEach(x => add(x,'mirror',1,'mirror'));
    shiftSet(n,[1,2,3]).forEach(x => add(x,'shift',1,'shift'));
  });
  const fellKeys = new Set(pool.draws.map(keyOf));
  const BOOKTYPE = { both:'A', one:'A', watch:'A', twobook:'A', followup:'F', relative:'R', g25:'G', redside:'S' };
  const ranked = [...H.values()]
    .map(e => ({ num:e.num, types:e.types.size, sources:e.sources,
                 hasBoth:e.types.has('both'), fell:fellKeys.has(keyOf(e.num)),
                 // which BOOKS (not methods) point here — almanac / followups / relatives
                 srcBooks:[...new Set([...e.types].map(t=>BOOKTYPE[t]).filter(Boolean))].sort() }))
    .filter(e => !e.fell)
    .sort((a,b) => b.types - a.types || b.sources - a.sources || (b.hasBoth-a.hasBoth) || a.num.localeCompare(b.num));
  if(!boxMode()) return ranked;
  /* In box mode, one boxed number must occupy ONE tile. Without this, a wide
     window fills the whole board with arrangements of the same 3-4 surviving
     boxes (757/775/577...) and reads as massive convergence when it is really
     one box repeated. Keep the strongest arrangement; note the others on it. */
  const seen = new Map(), out = [];
  ranked.forEach(e => {
    const bk = sortD(e.num);
    if(seen.has(bk)) seen.get(bk).boxMates.push(e.num);
    else { e.boxMates = []; seen.set(bk, e); out.push(e); }
  });
  return out;
}

/* ══════════ RENDER ══════════ */
function bookBadge(r){
  if(activeBooks().length < 2) return '';
  const b = r.books.join('+');
  const cls = r.books.length > 1 ? ' both' : '';
  return '<span class="bk'+cls+'">'+r.books.map(x=>"'"+x).join('+')+'</span>';
}
function relHTML(r){
  return r.rel.map((x,i) => {
    const t = r.hit[i] && r.src ? siteTxt(r.src[i]) : '';
    return '<span class="rel'+(r.hit[i]?' hit':'')+'"'+(t?' title="'+t+'"':'')+'>'+x+'</span>';
  }).join('<span class="arrow"> · </span>');
}
function srcNote(r){
  const multi = r.books && r.books.length > 1;
  const out = [];
  const one = (e, bk) => {
    if(!e || !e.src) return;
    e.rel.forEach((x,i) => {
      if(e.hit[i] && e.src[i])
        out.push((multi ? '<span class="bk">&rsquo;'+bk+'</span> ' : '') + x + ' &mdash; ' + siteTxt(e.src[i]));
    });
  };
  one(r, r.books ? r.books[0] : '');
  if(r.alt) r.alt.forEach((a,i) => one(a, r.books ? r.books[i+1] : ''));
  return out.join('<br>');
}
/* which number each book is still waiting on (partial rows) */
function wantNote(r){
  const multi = r.books && r.books.length > 1;
  const out = [];
  const add = (w, bk) => { if(w) out.push('watch <b>'+w+'</b>' + (multi ? ' <span class="bk">&rsquo;'+bk+'</span>' : '')); };
  add(r.want, r.books ? r.books[0] : '');
  if(r.alt) r.alt.forEach((a,i) => add(a.want, r.books ? r.books[i+1] : ''));
  return out.join('<br>');
}
function rowHTML(r, cls, note){
  const multi = r.books && r.books.length > 1;
  const lab = bk => multi ? '<span class="bk">&rsquo;'+bk+'</span>' : '';
  let pairs = lab(r.books ? r.books[0] : '') + relHTML(r);
  if(r.alt) r.alt.forEach((a,i) => {
    pairs += '<span class="arrow">&nbsp;&nbsp;</span>' + lab(r.books[i+1]) + relHTML(a);
  });
  return '<div class="arow '+cls+(multi?' twobook':'')+' fade">'+
         '<span class="key">'+r.key+'</span>'+
         '<span class="arrow">&larr;</span>'+pairs+
         (note?'<span class="note">'+note+'</span>':'')+'</div>';
}

function render(){
  const states = Object.keys(DB.byState).filter(s => DB.byState[s].length);
  const latest = DB.dayLog[DB.dayLog.length-1];
  const ids = ['confirmed','partial','watchList','playNext','duePairs','chainBody'];
  if(!latest){
    ids.forEach(i => document.getElementById(i).innerHTML='<div class="empty">Add a day to begin.</div>');
    document.getElementById('heatBoard').innerHTML='<div class="heatempty">Add a day to begin.</div>';
    document.getElementById('seriesBody').innerHTML='<div class="empty">Add a day to begin.</div>';
    document.getElementById('seriesCount').textContent='';
    document.getElementById('seriesBase').innerHTML='';
    ['confCount','partCount','watchCount','confBase','watchBase'].forEach(i=>document.getElementById(i).textContent='');
    document.getElementById('meter').innerHTML='';
    document.getElementById('almanacScore').innerHTML='';
    document.getElementById('pairAccuracy').innerHTML='';
    document.getElementById('stateLog').innerHTML='No history yet.';
    document.getElementById('stCount').textContent='';
    document.getElementById('stLive').innerHTML='<div class="empty">Add a day to begin.</div>';
    document.getElementById('stScore').innerHTML='';
    document.getElementById('stPerState').innerHTML='';
    document.getElementById('stBase').innerHTML='';
    renderStateNumbers();
    renderPairs();
    renderVibrations();   // the book's page stands on its own with no history
    return;
  }
  const K = lookback();
  const pool = pooledDays(K);
  const draws = pool.draws;
  const an = almanacAnalysis(pool);
  const modeTxt = boxMode() ? 'any order' : 'exact order';
  const winTxt = pool.days === 1 ? 'today' : 'the last ' + pool.days + ' days';
  /* the heat board keeps the two almanacs under the A tag and gives Grandma 2025
     and Red Side their own letters, so the badge says which books, not just "A" */
  const anHeat = use25() ? almanacAnalysis(pool, activeBooks().filter(b=>b!=='25')) : an;
  const heat = heatScore(pool, anHeat);   // computed once, used by heat board + watch marking
  const ser = seriesAnalysis(pool);   // series priming

  /* both relatives landed */
  const cEl = document.getElementById('confirmed');
  const twoBook = an.confirmed.filter(c => c.books.length > 1).length;
  document.getElementById('confCount').textContent =
    an.confirmed.length + ' flagged' + (twoBook ? ' · ' + twoBook + ' in both books' : '');
  cEl.innerHTML = an.confirmed.length
    ? capList(an.confirmed, 'conf', 40, r => rowHTML(r,'confirmed',
        srcNote(r) + (UNCONFIRMED.has(r.key) ? '<br><i>row unconfirmed in transcription</i>' : '')))
    : '<div class="empty">No number had a full pair of relatives land within '+winTxt+'.</div>';
  const nBooks = activeBooks().length;
  document.getElementById('confBase').innerHTML =
    (nBooks > 1
      ? 'A book&rsquo;s full pair of relatives landed in '+winTxt+' ('+modeTxt+') while the number itself did not. '+
        'Rows tagged <b>&rsquo;16</b> or <b>&rsquo;17</b> mean that edition&rsquo;s pair came in; rows showing both tags '+
        'mean each edition&rsquo;s own pair landed, and those sort to the top.'
      : 'Both relatives of the number landed somewhere in '+winTxt+' ('+modeTxt+'), and the number itself did not.') +
    ' They do not have to land on the same day or in the same state &mdash; the note on each row says where and when. '+
    'This is the most selective signal the tables produce.';

  /* one relative landed */
  const pEl = document.getElementById('partial');
  document.getElementById('partCount').textContent = an.partial.length + ' flagged';
  pEl.innerHTML = an.partial.length
    ? capList(an.partial, 'part', 25, r => rowHTML(r,'', wantNote(r)+'<br>'+srcNote(r)))
    : '<div class="empty">Nothing landed alongside one of its own relatives in '+winTxt+'.</div>';

  /* watch list — parent led, relatives on the way.
     Progress marker: 1/2 = one relative already followed (closest to completing,
     sorted to top), 0/2 = neither has yet. Strong ones (heat top 12) marked hot. */
  const wEl = document.getElementById('watchList');
  const hotSet = new Set(heat.slice(0, 12).map(h => h.num));
  // 1/2 rows: parent fell, one relative followed -> watch the remaining one
  const oneLeft = an.partial.map(pn => {
    const gotIdx = pn.hit[0] ? 0 : 1;      // which relative already came
    return { key: pn.key, rel: pn.rel, done: pn.rel[gotIdx], want: pn.want, prog: 1, books: pn.books };
  });
  // 0/2 rows: parent fell, neither relative yet
  const noneYet = an.watch.map(r => ({ key: r.key, rel: r.rel, want: null, prog: 0, books: r.books }));
  const combined = [...oneLeft, ...noneYet];       // 1/2 first
  document.getElementById('watchCount').textContent =
    oneLeft.length + ' at 1/2 · ' + noneYet.length + ' at 0/2 · ' + pool.days + 'd window';

  if(combined.length){
    let nSpent = 0;
    const rows = (EXPANDED['watch'] ? combined : combined.slice(0,90)).map(r => {
      const hot = hotSet.has(r.key) || r.rel.some(x => hotSet.has(x));
      const play = r.prog === 1 ? [r.want] : r.rel;     // what you would actually buy
      const playHTML = play.map(x => {
        const sp = lastLanded(x);
        const fresh = sp && sp.ago <= K + 1;      // dropped just outside the window = spent
        if(fresh) nSpent++;
        const badge = sp
          ? '<span class="wage'+(fresh?' fresh':'')+'" title="last dropped '+agoTxt(sp.ago)+
            ' &mdash; '+sp.states.slice(0,3).join(', ')+'">'+sp.ago+'d</span>'
          : '<span class="wage cold" title="has not dropped anywhere in your '+
            (DB.dayLog||[]).length+' logged days">none</span>';
        return '<span class="wplay'+(fresh?' spent':'')+'">'+x+badge+'</span>';
      }).join('<span class="wa">&middot;</span>');
      const note = 'from ' + r.key + (r.prog===1 ? ' &middot; ' + r.done + ' already in' : '');
      const tag = '<span class="prog p'+r.prog+'">'+r.prog+'/2</span>';
      return '<div class="wrow'+(hot?' hot':'')+(r.prog===1?' near':'')+'">'+tag+
             bookBadge(r)+playHTML+'<span class="wtrig">'+note+'</span></div>';
    }).join('');
    wEl.innerHTML = '<div class="watchgrid">'+rows+'</div>'+
      (combined.length>90
        ? '<div class="baseline"><span class="chip more" onclick="toggleMore(\'watch\')">'+
          (EXPANDED['watch'] ? '&minus; show fewer' : '+'+(combined.length-90)+' more')+'</span></div>'
        : '');
  } else {
    wEl.innerHTML = '<div class="empty">Nothing fell with relatives still pending in '+winTxt+'.</div>';
  }
  const pct = (an.flagged.size/10).toFixed(0);
  document.getElementById('watchBase').innerHTML =
    'A parent number fell and its relatives haven&rsquo;t all followed yet. '+
    '<b>The big number on each row is the one the book points at</b> &mdash; the small note says which number '+
    'triggered it. <b>1/2</b> means one relative already came, so only one is left; <b>0/2</b> means neither has. '+
    'The badge is <b>how many days since that number last dropped anywhere</b> in your log; hover it for where. '+
    'Red means it dropped just outside the window, so the move is most likely already spent. '+
    '<b>Read that badge carefully.</b> Over '+(DB.dayLog||[]).length+' logged days almost every boxed number has '+
    'come up at some point &mdash; a plain &ldquo;this already came&rdquo; flag would mark about 97% of this list and '+
    'narrow nothing, the same reason Bold Relatives is lookup-only. Only recency tells you anything, and even then '+
    'it tells you the move is done, never that the number is due. '+
    'Watching <b>'+an.flagged.size+' of 1000</b> ('+pct+'% of the field) '+
    'over '+winTxt+'; a wider window flags more, so watch that count. The scorekeeping section tracks '+
    'whether these actually follow more than chance would give you.';

  /* shortlist — same box-dedupe as the heat board: one boxed number, one slot */
  const N = parseInt(document.getElementById('topN').value,10) || 5;
  let boardAll = scoreBoard(pool, an).filter(p => !p.fell);
  if(boxMode()){ const sb=new Set();
    boardAll = boardAll.filter(p=>{ const k=sortD(p.num);
      if(sb.has(k)) return false; sb.add(k); return true; }); }
  const board = boardAll.slice(0, N);

  /* ── heat board (top) ──
     Rank-capped so the focus list stays short no matter how many states load:
     the strongest few go red, the next tier orange. Ties broken by source count. */
  const RED_MAX = 6, ORANGE_MAX = 12;
  const hb = document.getElementById('heatBoard');
  if(heat.length){
    const shown = heat.slice(0, ORANGE_MAX);
    lastHeatNums = shown.map(h=>h.num);
    hb.innerHTML = shown.map((h, i) => {
      const tier = i < RED_MAX ? 'red' : 'orange';
      const BN = { A:'almanac', F:'Follow Ups', R:'Relatives', G:'Grandma 2025', S:'Red Side' };
      const bk = (h.srcBooks||[]);
      /* yellow = every ticked book points here (almanacs count as one letter) */
      const nTicked = (activeBooks().filter(b=>b!=='25').length?1:0)+(useFU()?1:0)+(useREL()?1:0)+(use25()?1:0)+(useRS()?1:0);
      const badge = bk.length
        ? '<div class="hbk'+(bk.length>=nTicked && nTicked>=2?' all':'')+'">'+bk.join('')+'</div>' : '';
      const mates = (h.boxMates && h.boxMates.length)
        ? ' · same box: '+h.boxMates.join(', ') : '';
      return '<div class="htile '+tier+' fade" onclick="copyNum(\''+h.num+'\')" title="'+
             h.types+' signal types across '+h.sources+' sources'+
             (bk.length ? ' · books: '+bk.map(x=>BN[x]).join(', ') : '')+mates+'">'+
             '<span class="hbar"></span>'+badge+markFor(h.num,'heat')+
             '<div class="hn">'+h.num+'</div>'+
             '<div class="hc">'+h.types+' sig · '+h.sources+' src'+
             (h.boxMates && h.boxMates.length ? ' · +'+h.boxMates.length+' arr' : '')+'</div></div>';
    }).join('');
    /* Wide-window honesty check: this board HIDES numbers that already fell
       (boxed) in the window. Once the window is wide enough that most of the
       field has landed somewhere, what survives is just the few double/triple
       boxes that happen not to have shown — an absence list, not convergence. */
    if(pool.days > 1){
      let fc=0; new Set(pool.draws.map(n=>sortD(n))).forEach(k=>{ fc+=PERM_COUNT[k]||0; });
      const pct = fc/10;
      if(pct >= 40) hb.innerHTML += '<div class="heatempty" style="flex-basis:100%;margin-top:10px;opacity:.85">'+
        '&#9888; Window is '+pool.days+' days: <b>'+pct.toFixed(0)+'% of the field has already landed (boxed)</b> and is '+
        'filtered off this board. What survives a window this wide is mostly the few double/triple boxes that '+
        'haven&rsquo;t hit anywhere yet &mdash; an absence list, not convergence, and draws carry no memory: a box '+
        'that hasn&rsquo;t shown in '+pool.days+' days is no likelier tonight than it was then. '+
        'Set <b>Look back to 1 day</b> for the ranking this board was built for.</div>';
    }
  } else {
    hb.innerHTML = '<div class="heatempty">Nothing converged today. Add more states or widen the window.</div>';
  }
  document.getElementById('playNext').innerHTML = board.length
    ? board.map(p =>
        '<div class="pick fade"><span class="n" onclick="copyNum(\''+p.num+'\')" title="Click to copy">'+
        p.num+'</span><span class="why">'+p.why.join(' &middot; ')+'<br>score '+p.score+'</span></div>').join('')
    : '<div class="empty">Nothing to rank yet.</div>';

  /* pairs missing */
  const seen = new Set(latest.appeared);
  const missing = ALL_PAIRS.filter(p => !seen.has(p));
  document.getElementById('duePairs').innerHTML = missing.length
    ? '<div>'+missing.map(p=>'<span class="chip due">'+p+'x</span>').join('')+'</div>'+
      '<div class="baseline">'+missing.length+' of 55 pairs did not show today.</div>'
    : '<div class="empty">All 55 pairs showed today.</div>';

  /* ── series priming panel ── */
  const sBody = document.getElementById('seriesBody');
  const hotSet2 = new Set(heat.slice(0,12).map(h=>h.num));
  document.getElementById('seriesCount').textContent =
    (ser.dropped.length ? ser.dropped.length + ' dropped · ' : '') +
    ser.primed.length + ' priming · ' + ser.dormant.length + ' quiet';
  const waitTxt = e => e.sinceDrop === null
    ? 'never dropped in '+e.totalDays+' logged day'+(e.totalDays===1?'':'s')
    : (e.sinceDrop === 0 ? 'dropped today'
       : 'last dropped '+e.sinceDrop+' day'+(e.sinceDrop===1?'':'s')+' ago');
  const srow = (e, cls) => {
    const hot = hotSet2.has(e.series);
    const chips = e.ledBy.sort((a,b)=>a.ago-b.ago).map(d =>
      '<span class="sdbl"><b>'+d.double+'</b> · '+agoTxt(d.ago)+'</span>').join('');
    return '<div class="srow'+(hot?' hot':'')+(cls?' '+cls:'')+'">'+
      '<span class="scnt">'+e.count+'/4</span>'+
      '<span class="sser">'+e.series+'</span>'+
      '<span class="swait">'+waitTxt(e)+'</span>'+
      '<div class="sled">'+(chips || '<span class="snone">nothing since</span>')+'</div></div>';
  };
  let sHtml = '';
  if(ser.dropped.length){
    sHtml += '<div class="dropbox"><div class="drophd">&#9679; DROPPED TODAY &mdash; count restarts</div>'+
      ser.dropped.map(e => {
        const st = (e.drop.states||[]).slice(0,6)
          .map(x => '<span class="sdbl"><b>'+x.num+'</b> · '+nm(x.state)+'</span>').join('');
        return '<div class="srow dropped"><span class="scnt hit">IN</span>'+
          '<span class="sser">'+e.series+'</span>'+
          '<span class="swait">relatives reset to 0/4</span>'+
          '<div class="sled">'+st+'</div></div>';
      }).join('')+'</div>';
  }
  if(ser.primed.length){
    sHtml += '<div class="grp open">&#10003; PRIMING &mdash; doubles in since the last drop <span class="gn">'+
             ser.primed.length+'</span></div>' + ser.primed.map(e=>srow(e,'')).join('');
  }
  if(ser.dormant.length){
    sHtml += '<div class="grp">QUIET &mdash; nothing since the last drop <span class="gn">'+
             ser.dormant.length+'</span></div>' + ser.dormant.map(e=>srow(e,'faded')).join('');
  }
  sBody.innerHTML = sHtml || '<div class="empty">No series activity yet.</div>';
  document.getElementById('seriesBase').innerHTML =
    'When a series lands it shows at the top as <b>dropped</b> and its count <b>restarts at 0/4</b> &mdash; '+
    'doubles that led the previous appearance are spent and stop counting. '+
    'A series is <b>priming</b> when doubles have landed since its last drop; the count is how many of its '+
    'four, and the wait is measured across every day you have logged, not just the window. '+
    '<b>Read the wait carefully.</b> A series that has not dropped in 20 days is not more likely to drop '+
    'tomorrow than one that dropped yesterday &mdash; the draws carry no memory of the gap. What the wait '+
    'is genuinely good for is the opposite: seeing that a series just landed, so you do not chase one '+
    'that has already come. The scorekeeping section tracks whether a primed series follows more than chance.';

  renderConvergence(pooledDraws());
  /* both lists are now computed for this render — stamp them so the next day
     can mark each number came (X) or not-yet (tick) */
  snapshotLists(lastHeatNums, lastConvKeys);
  renderChain(latest.dayStates, DB.dayLog.slice(-lookback()));
  renderHistoryScores();
  renderPairAccuracy();
  renderStateView();
  renderStateNumbers();
  renderPairs();
  renderVibrations();
  document.getElementById('stateLog').innerHTML = states.sort()
    .map(s=>'<span class="chip st">'+nm(s)+' '+DB.byState[s].length+'</span>').join('');
}

/* ══════════ PAIR RULES (state-specific rule sheet) ══════════
   A "pair" is two digits present in a number: pair 00 = two zeros, pair 63 = a 6 and a 3.
   Rule 4 tested at lift 1.00 on the first four logged days — kept here because the
   targets are narrow (7.9% of the field vs the almanac's ~36%), not because it's proven. */
function hasPair(n, p){
  const a = p[0], b = p[1];
  if(a === b) return (n.split(a).length - 1) >= 2;
  return n.indexOf(a) >= 0 && n.indexOf(b) >= 0;
}
/* Only narrow rules are included: each target set covers 3-15% of the 1000-number
   field. Rules whose targets cover 27-66% (e.g. "brings a DOUBLE", "look for
   number 3, 4 or 8") are deliberately left out — they fire constantly and narrow
   nothing. `cov` is the share of all numbers the target matches. */
const PAIR_RULES = [
  { id:2,  trig:{pair:'0'},   trigTxt:'number 0',  tgt:[{pair:'24'},{pair:'63'}],            tgtTxt:'pair 24 or 63',      cov:.109 },
  { id:4,  trig:{pair:'00'},  trigTxt:'pair 00',   tgt:[{pair:'66'},{pair:'63'}],            tgtTxt:'pair 66 or 63',      cov:.079 },
  { id:5,  trig:{pair:'01'},  trigTxt:'pair 01',   tgt:[{pair:'32'},{pair:'28'}],            tgtTxt:'pair 32 or 28',      cov:.103 },
  { id:6,  trig:{pair:'03'},  trigTxt:'pair 03',   tgt:[{pair:'59'}],                        tgtTxt:'pair 59',            cov:.054 },
  { id:8,  trig:{pair:'09'},  trigTxt:'pair 09',   tgt:[{pair:'78'}],                        tgtTxt:'pair 78',            cov:.054 },
  { id:9,  trig:{pair:'11'},  trigTxt:'pair 11',   tgt:[{series:1},{pair:'00'}],             tgtTxt:'series or pair 00',  cov:.088 },
  { id:11, trig:{pair:'25'},  trigTxt:'pair 25',   tgt:[{pair:'25'},{pair:'13'}],            tgtTxt:'pair 25 again or 13',cov:.109 },
  { id:17, trig:{pair:'54'},  trigTxt:'pair 54',   tgt:[{pair:'00'}],                        tgtTxt:'pair 00',            cov:.028 },
  { id:20, trig:{pair:'58'},  trigTxt:'pair 58',   tgt:[{pair:'78'},{pair:'30'}],            tgtTxt:'pair 78 or 30',      cov:.106 },
  { id:22, trig:{pair:'93'},  trigTxt:'pair 93',   tgt:[{pair:'57'}],                        tgtTxt:'pair 57',            cov:.054 },
  { id:27, trig:{pair:'66'},  trigTxt:'pair 66',   tgt:[{pair:'35'},{pair:'38'},{pair:'58'}],tgtTxt:'pair 35, 38 or 58',  cov:.152 },
  { id:28, trig:{pair:'77'},  trigTxt:'pair 77',   tgt:[{pair:'24'},{pair:'29'},{pair:'49'}],tgtTxt:'pair 24, 29 or 49',  cov:.152 },
  { id:30, trig:{pair:'33'},  trigTxt:'pair 33',   tgt:[{pair:'88'}],                        tgtTxt:'pair 88',            cov:.028 },
  { id:31, trig:{pair:'83'},  trigTxt:'pair 83',   tgt:[{pair:'33'}],                        tgtTxt:'pair 33',            cov:.028 },
  { id:33, trig:{series:1},   trigTxt:'a series',  tgt:[{series:1},{trip:1},{ftrip:1}],      tgtTxt:'series, false trip or trip' },
  /* ── added from the full rule sheet (Oct 10). Rule 1 is folded into 21 (same trigger, 0 is in both).
     Rule 3 (doubles with 0 from the last draw) is computed per draw and shown in its own row above. ── */
  { id:7,  trig:{pair:'04'},  trigTxt:'pair 04',   tgt:[{dbl:1}],                            tgtTxt:'a double' },
  { id:10, trig:{pair:'23'},  trigTxt:'pair 23',   tgt:[{digits:['6','9']}],                 tgtTxt:'a 6, a 9 or both' },
  { id:12, trig:{pair:'34'},  trigTxt:'3 and 4 together', tgt:[{dbl:1}],                     tgtTxt:'a double (within 2 draws)' },
  { id:13, trig:{pair:'36'},  trigTxt:'pair 36',   tgt:[{dbl:1}],                            tgtTxt:'a double' },
  { id:14, trig:{pair:'44'},  trigTxt:'pair 44',   tgt:[{pair:'6'}],                         tgtTxt:'a 6' },
  { id:15, trig:{pair:'47'},  trigTxt:'pair 47',   tgt:[{dbl:1}],                            tgtTxt:'a double' },
  { id:16, trig:{pair:'49'},  trigTxt:'pair 49',   tgt:[{pair:'7'}],                         tgtTxt:'a 7' },
  { id:18, trig:{pair:'56'},  trigTxt:'pair 56',   tgt:[{pair:'3'}],                         tgtTxt:'a 3 and/or pair 37' },
  { id:19, trig:{pair:'57'},  trigTxt:'pair 57',   tgt:[{digits:['0','9']}],                 tgtTxt:'a 0 or 9' },
  { id:21, trig:{pair:'89'},  trigTxt:'pair 89',   tgt:[{pair:'0'},{pair:'25'}],             tgtTxt:'a 0 (rule 1) or pair 25' },
  { id:23, trig:{dbl:1},      trigTxt:'a double',  tgt:[{digits:['3','4','8']}],             tgtTxt:'a 3, 4 or 8' },
  { id:24, trig:{sum:[5]},    trigTxt:'sum 5 in the evening', trigSlot:'e', tgt:[{pair:'46'}], tgtTxt:'pair 46 next draw' },
  { id:25, trig:{odd3:1},     trigTxt:'3 odd digits', tgt:[{ftrip:1},{trip:1}],             tgtTxt:'false trip or trip' },
  { id:26, trig:{g:4,trip4:1},trigTxt:'a trip in Pick 4', tgt:[{series:1},{g:4,series4:1}], tgtTxt:'a series in Pick 3 or Pick 4' },
  { id:29, trig:{box:['777']},trigTxt:'777 in any state', anyState:true, tgt:[{box:['899']},{g:4,contains:'899'}], tgtTxt:'989 in Pick 3 or Pick 4, any state' },
  { id:32, trig:{sum:[13,14]},trigTxt:'sum 13 or 14', tgt:[{ftrip:1},{dbl:1}],               tgtTxt:'false trip or more doubles' },
  { id:34, trig:{ftrip:1},    trigTxt:'a false trip', tgt:[{ftrip:1},{trip:1}],              tgtTxt:'another false trip or a trip' },
  { id:35, trig:{box:['129','034']}, trigTxt:'219', tgt:[], tgtTxt:'304 (either one brings the other)',
    dyn: n => [{box:[sortD(n)==='129' ? '034' : '129']}], cov:.006 },
  { id:36, trig:{box:['236','127']}, trigTxt:'236', tgt:[], tgtTxt:'217 (either one brings the other)',
    dyn: n => [{box:[sortD(n)==='236' ? '127' : '236']}], cov:.006 }
];
function matchSpec(n, sp){
  if(n.length !== (sp.g || 3)) return false;     /* Pick 4 specs only see Pick 4 draws */
  if(sp.pair !== undefined) return sp.pair.length === 1 ? n.indexOf(sp.pair) >= 0 : hasPair(n, sp.pair);
  if(sp.digits) return sp.digits.some(d => n.indexOf(d) >= 0);
  if(sp.series) return isSeries(n);
  if(sp.trip)   return isTriple(n);
  if(sp.dbl)    return isDouble(n);
  if(sp.ftrip)  return isFalseTrip(n);
  if(sp.sum)    return sp.sum.indexOf(digitSum(n)) >= 0;
  if(sp.odd3)   return allOdd(n);
  if(sp.box)    return sp.box.indexOf(sortD(n)) >= 0;
  if(sp.trip4)  return isTrip4(n);
  if(sp.series4)return isSeries4(n);
  if(sp.contains) return containsDigits(n, sp.contains);
  return false;
}
const ruleFires  = (n, r) => r.trig.some ? r.trig.some(t => matchSpec(n, t)) : matchSpec(n, r.trig);
/* static target test; dyn rules (target depends on the triggering number) use ruleTargetFor */
const ruleTarget = (n, r) => r.tgt.some(t => matchSpec(n, t));
const ruleTargetFor = (n, r, trigN) => r.dyn ? r.dyn(trigN).some(t => matchSpec(n, t)) : ruleTarget(n, r);
const ORIG_RULE_IDS = new Set([2,4,5,6,8,9,11,17,20,22,27,28,30,31,33]);
PAIR_RULES.forEach(r => {
  r.orig = ORIG_RULE_IDS.has(r.id);
  if(r.cov === undefined){ let c = 0;
    for(let i=0;i<1000;i++){ if(ruleTarget(String(i).padStart(3,'0'), r)) c++; } r.cov = c/1000; }
  r.wide = r.cov > 0.2;
});
/* rule 3: doubles made from each digit of the last draw with a 0 (247 -> 220, 440, 770), boxed;
   played in the SAME slot of the next draw (day to day, night to night) */
const rule3Plays = n => [...new Set(n.split('').filter(d => d !== '0'))].map(d => sortD(d+d+'0'));
/* evaluate one trigger/target spec against a number */

/* Expandable overflow: every truncated list gets a real "+N more" toggle.
   Nothing in this dashboard hides items silently — a hidden "already came"
   number is exactly the kind of thing that costs money. */
const EXPANDED = {};
let lastConvKeys = {}, lastHeatNums = [];
function toggleMore(id){
  EXPANDED[id] = !EXPANDED[id];
  render();
}
/* cap a list, returning html + a clickable +N more chip */
function capList(items, id, cap, fmt){
  const open = !!EXPANDED[id];
  const shown = open ? items : items.slice(0, cap);
  let h = shown.map((it, i) => fmt(it, i, shown)).join('');
  if(items.length > cap)
    h += '<span class="chip more" onclick="toggleMore(\''+id+'\')">'+
         (open ? '&minus; show fewer' : '+'+(items.length-cap)+' more')+'</span>';
  return h;
}

/* ══════════ PREDICTION SNAPSHOTS / CARRYOVER MARKS ══════════
   When a day is added, the heat board and the four-book list are saved as a
   snapshot stamped with the day count at that moment. From then on, every number
   on those lists is marked against the draws that came AFTER it was listed:
     X  = it has since landed somewhere  (spent — the move is done)
     tick = not yet  (still open)
   Same logic as the rule sheet's already-came / still-open split, so a number
   can't sit on the board looking live after it has already dropped. */
function snapshotLists(heatNums, convKeys){
  if(VIEW_ACTIVE) return;
  DB.snaps = DB.snaps || [];
  const at = DB.dayLog.length;
  if(DB.snaps.length && DB.snaps[DB.snaps.length-1].at === at) return;  // one per day
  const conv = Array.isArray(convKeys) ? convKeys.slice() : {};
  if(!Array.isArray(convKeys)) Object.keys(convKeys||{}).forEach(l => { conv[l] = (convKeys[l]||[]).slice(); });
  DB.snaps.push({ at, heat:(heatNums||[]).slice(), conv });
  if(DB.snaps.length > 60) DB.snaps.splice(0, DB.snaps.length-60);
  save();
}
/* first day-index at which this number appeared on the given list */
function firstListedAt(key, which){
  const snaps = DB.snaps || [];
  for(let i=0;i<snaps.length;i++){
    let arr = which==='heat' ? snaps[i].heat : snaps[i].conv;
    if(arr && !Array.isArray(arr)) arr = [].concat.apply([], Object.values(arr));
    if(arr && arr.some(x => sortD(x) === sortD(key))) return snaps[i].at;
  }
  return null;
}
/* the most recent snapshot taken BEFORE today — i.e. yesterday's published list.
   Guarded so a re-render (which re-stamps today) can't compare today against itself. */
function prevSnap(){
  const snaps = DB.snaps || [];
  for(let i = snaps.length - 1; i >= 0; i--)
    if(snaps[i].at < DB.dayLog.length) return snaps[i];
  return null;
}
/* status of a listed number:
     new  = it was NOT on yesterday's list — generated fresh this run
     came = it has landed since it was first listed
     open = listed before, still hasn't landed */
function listStatus(key, which, tier){
  const ps = prevSnap();
  if(ps){
    let arr;
    if(which === 'heat') arr = ps.heat;
    else if(ps.conv && !Array.isArray(ps.conv)) arr = ps.conv[tier] || [];   // per-tier
    else arr = ps.conv || [];                                               // legacy flat
    const wasListed = (arr || []).some(x => sortD(x) === sortD(key));
    if(!wasListed) return { state:'new', days:0 };
  }
  const at = firstListedAt(key, which);
  if(at === null) return { state:'new', days:0 };
  const since = DB.dayLog.slice(at);           // days drawn AFTER it was listed
  for(let i=0;i<since.length;i++){
    const hit = (since[i].draws||[]).filter(n => sortD(n) === sortD(key));
    if(hit.length) return { state:'came', days:i+1, on:hit, ago:since.length-i-1 };
  }
  return { state:'open', days:since.length };
}
function markFor(key, which, tier){
  if(VIEW_ACTIVE && VIEW && VIEW.next){
    const h = VIEW.next[sortD(key)];
    return h ? '<span class="mk x" title="came on '+VIEW.label+': '+h.map(x=>nm(x.c)+' '+x.n).join(', ')+'">&#10005;</span>'
             : '<span class="mk ok" title="did not come on '+VIEW.label+'">&#10003;</span>';
  }
  const st = listStatus(key, which, tier);
  if(st.state === 'new')  return '';
  if(st.state === 'came')
    return '<span class="mk x" title="landed '+st.on.join(', ')+' &mdash; '+
           st.days+' day'+(st.days>1?'s':'')+' after being listed">&#10005;</span>';
  return '<span class="mk ok" title="not yet, '+st.days+' day'+(st.days>1?'s':'')+
         ' on the list">&#10003;</span>';
}

/* ══════════ FOUR-BOOK CONVERGENCE ══════════
   Each book points from today's draws to target numbers. A number's
   convergence score is how many DIFFERENT books point at it.
   Measured result on the first four logged days: 4-book agreement narrowed the
   board to ~8 boxed picks (5% of the field) at lift 1.32 — but when all four
   books were replaced with random tables, 19% of those fake runs matched or beat
   1.32, and fake convergence averaged 1.02. The narrowing is real; the claim that
   what survives is more likely is not established. The tracker below measures it. */
function bookTargets(draws){
  const on=booksOn(), out={};
  const add=(name,fn)=>{ const s=new Set(); draws.forEach(n=>fn(n).forEach(t=>s.add(sortD(t)))); out[name]=s; };
  if(on.has('16'))  add('2016',         n=>ALMANAC[n]||[]);
  if(on.has('17'))  add('2017',         n=>ALMANAC17[n]||[]);
  if(on.has('fu'))  add('Follow Ups',   n=>FOLLOWUPS[n]?[FOLLOWUPS[n]]:[]);
  if(on.has('rel')) add('Relatives',    n=>RELATIVES[sortD(n)]?[RELATIVES[sortD(n)]]:[]);
  if(on.has('25'))  add('Grandma 2025', n=>ALMANAC25[n]||[]);
  if(on.has('rs'))  add('Red Side',     n=>BOLD_REL[sortD(n)]||[]);
  return out;
}
const convLevels = () => { const N=booksOn().size; const L=[]; for(let i=2;i<=N;i++) L.push(i); return L; };
function convergence(draws){
  const t = bookTargets(draws);
  const names = Object.keys(t);
  const score = {};      // box-key -> [books that point at it]
  names.forEach(nme => t[nme].forEach(k => { (score[k] = score[k] || []).push(nme); }));
  return { score, targets:t };
}
/* forward test, per agreement level, against what coverage alone predicts */
function convergenceScore(){ return histMemo('convergenceScore', convergenceScoreRun); }
function convergenceScoreRun(){
  const v = DB.dayLog.filter(e => e.draws && e.draws.length);
  const out = {};
  convLevels().forEach(lvl => {
    let hits = 0, exp = 0, picks = 0, n = 0;
    for(let d = 0; d < v.length - 1; d++){
      const { score } = convergence(v[d].draws);
      const tgt = new Set(Object.keys(score).filter(k => score[k].length >= lvl));
      if(!tgt.size) continue;
      let cov = 0;
      for(let i = 0; i < 1000; i++) if(tgt.has(sortD(String(i).padStart(3,'0')))) cov++;
      const nxt = v[d+1].draws;
      hits += nxt.filter(x => tgt.has(sortD(x))).length;
      exp  += nxt.length * cov / 1000;
      picks += tgt.size; n++;
    }
    out[lvl] = { hits, exp, lift: exp > 0 ? hits/exp : 0, picks: n ? Math.round(picks/n) : 0, days:n };
  });
  return out;
}

/* Per-rule collapse state. Rules default to CLOSED so the panel stays compact —
   click a rule header to open just that one. Persisted like the panel collapse. */
const RKEY = 'almanac_rulecollapse_v1';
let RULE_OPEN = {};
try { RULE_OPEN = JSON.parse(localStorage.getItem(RKEY)) || {}; } catch(e) { RULE_OPEN = {}; }
function toggleRule(id){
  RULE_OPEN[id] = !RULE_OPEN[id];
  try { localStorage.setItem(RKEY, JSON.stringify(RULE_OPEN)); } catch(e){}
  const card = document.getElementById('prule-' + id);
  if(card) card.classList.toggle('open', !!RULE_OPEN[id]);
}
function setAllRules(open){
  PAIR_RULES.forEach(r => { RULE_OPEN[r.id] = open; });
  try { localStorage.setItem(RKEY, JSON.stringify(RULE_OPEN)); } catch(e){}
  render();
}

/* Forward-test every rule on the logged history: for each day the rule fired,
   count how many of the NEXT day's draws hit the target, against what the
   target's coverage predicts. Straight coverage — order-independent by nature. */
function ruleLifts(){ return histMemo('ruleLifts', ruleLiftsRun); }
function ruleLiftsRun(){
  const v = DB.dayLog.filter(e => e.draws && e.draws.length);
  const out = {};
  PAIR_RULES.forEach(rl => {
    let hits = 0, exp = 0, fired = 0;
    for(let d = 0; d < v.length - 1; d++){
      const trigs = v[d].draws.filter(n => ruleFires(n, rl));
      if(!trigs.length) continue;
      fired++;
      const nxt = v[d+1].draws;
      hits += nxt.filter(n => trigs.some(t => ruleTargetFor(n, rl, t))).length;
      exp  += nxt.length * rl.cov;
    }
    out[rl.id] = { hits, exp, fired, lift: exp > 0 ? hits/exp : 0 };
  });
  return out;
}

/* draws across the current lookback window */
function pooledDraws(){
  const w = DB.dayLog.slice(-lookback());
  const out = [];
  w.forEach(d => (d.draws||[]).forEach(n => out.push(n)));
  return out;
}

function renderConvergence(draws){
  const el = document.getElementById('convBody');
  if(!draws || !draws.length){ el.innerHTML='<div class="empty">Add a day to begin.</div>'; return; }
  const { score } = convergence(draws);
  const sc = convergenceScore();
  /* a target that has ALREADY landed inside the look-back window is spent
     whichever day it was listed — it gets the ✕ too, not a "new" star. The
     snapshot marks only knew "came after it was first listed", which let a
     number that dropped yesterday sit on the list looking live. */
  const fellWin = new Set(draws.map(sortD));
  const convState = (k, lvl) => fellWin.has(k) ? 'came' : listStatus(k,'conv',lvl).state;
  const convMark = (k, lvl) => { if(!fellWin.has(k)) return markFor(k,'conv',lvl);
    const L = lastLanded(k); return '<span class="mk x" title="already landed in this window'+(L?' — '+L.states.join(', ')+' '+agoTxt(L.ago):'')+'">&#10005;</span>'; };
  /* snapshot EVERY displayed tier (2+), not just full agreement — otherwise a
     number sitting at 2 or 3 books never gets a came / not-yet mark. */
  /* snapshot per tier: moving from 2-book up to 4-book counts as NEW to that
     tier, which is what "new numbers generated" means on the list you read. */
  const LV = convLevels(), N = LV.length ? LV[LV.length-1] : 0;
  lastConvKeys = {}; const byLvl = {};
  LV.forEach(l => { lastConvKeys[l] = []; byLvl[l] = []; });
  Object.keys(score).forEach(k => {
    const L = Math.min(score[k].length, N);
    if(L >= 2){ lastConvKeys[L].push(k); byLvl[L].push({ k, books: score[k] }); }
  });
  /* Group each tier by status so the list reads in blocks instead of scattered:
     came (X) first, then still-open (tick), then numbers new to the list.
     Within a group, numerical order. */
  const ORDER = { new:0, came:1, open:2 };
  Object.keys(byLvl).forEach(L => byLvl[L].sort((a,b) => {
    const L = Math.min(score[a.k].length,N);
    const sa = convState(a.k,L), sb = convState(b.k,Math.min(score[b.k].length,N));
    return (ORDER[sa] - ORDER[sb]) || (a.k < b.k ? -1 : 1);
  }));
  const fieldOf = set => { let c=0; for(let i=0;i<1000;i++) if(set.has(sortD(String(i).padStart(3,'0')))) c++; return c; };

  let h = '';
  LV.slice().reverse().forEach(lvl => {
    const rows = byLvl[lvl];
    if(!rows.length) return;
    const st = sc[lvl] || {};
    const setK = new Set(rows.map(r=>r.k));
    const field = fieldOf(setK);
    const liftTxt = (st.exp >= 5)
      ? '<span class="rlift'+(st.lift>=1.25?' up':(st.lift<=0.8?' dn':''))+'">lift '+st.lift.toFixed(2)+'</span>'
      : '<span class="rlift">no data yet</span>';
    h += '<div class="convlvl'+(lvl===N?' top':'')+'">'+
      '<div class="conv-h">'+(lvl===N ? 'ALL '+N+' BOOKS AGREE' : lvl+' books agree')+
        '<span class="rtags"><span class="rcount">'+rows.length+' boxed</span>'+
        '<span class="rcov">'+(field/10).toFixed(0)+'% of field</span>'+liftTxt+'</span></div>'+
      '<div class="conv-b">'+
        ['new','came','open'].map(st => {
          const grp = rows.filter(r => convState(r.k,lvl) === st);
          if(!grp.length) return '';
          const label = st==='came' ? '&#10005; already landed &mdash; in this window, or since it was listed'
                      : st==='open' ? '&#10003; still open &mdash; the live ones'
                      : '&#9733; NEW &mdash; generated this run, not on the last list';
          /* each group gets its own cap, so a long "came" block can never bury
             the still-open numbers behind a +more chip */
          return '<div class="grp '+st+'">'+label+' <span class="gn">'+grp.length+'</span></div>'+
            '<div class="grpwrap">'+capList(grp, 'conv'+lvl+st, 24, r =>
              '<span class="chip'+(lvl===N && st!=='came' ? ' due' : '')+' s-'+st+
              '" title="'+r.books.join(', ')+'">'+r.k+convMark(r.k,lvl)+'</span>')+'</div>';
        }).join('')+
      '</div>'+
    '</div>';
  });
  if(!h) h = N < 2 ? '<div class="empty">Tick at least two books above to see agreement.</div>'
              : '<div class="empty">No number is pointed at by two or more of the ticked books right now.</div>';
  /* the same trap the heat board warns about: a wide window means most boxes
     have already landed SOMEWHERE, so the ✕ marks say more about the window
     than about the books */
  const fellShare = fellWin.size / 220;
  const topShare = (N >= 2 && byLvl[N].length) ? fieldOf(new Set(byLvl[N].map(r=>r.k)))/1000 : 0;
  if(fellShare >= 0.6 || topShare >= 0.25)
    h = '<div class="status warn" style="display:block;margin-bottom:8px">&#9888; '+
      (fellShare >= 0.6 ? Math.round(fellShare*100)+'% of all boxed numbers have landed somewhere in this '+lookback()+'-day window, so most &#10005; marks here are the window, not the books. ' : '')+
      (topShare >= 0.25 ? 'The top tier covers '+Math.round(topShare*100)+'% of the field &mdash; agreement that wide narrows nothing'+(useRS()?' (Red Side alone points at ~11 numbers per draw)':'')+'. ' : '')+
      'For a list that can narrow, set Look back to 1 day'+(useRS()?' and untick Red Side':'')+'.</div>' + h;
  el.innerHTML = h;

  const top = N >= 2 ? byLvl[N].length : 0;
  document.getElementById('convCount').textContent =
    N < 2 ? bookNames().length+' book ticked' : (top ? top+' with all '+N+' books' : 'none with all '+N+' books')+' · '+N+' books ticked';
  document.getElementById('convBase').innerHTML =
    'Numbers shown boxed, grouped by how many of the ticked books point at them ('+bookNames().join(', ')+'). '+
    'Hover a number to see which books. '+
    '<b>This narrows the board hard</b> &mdash; full agreement typically leaves under 10 boxed picks, '+
    'about 5% of the field, down from 84% at one book. '+
    '<b>What the narrowing does not do is raise the odds.</b> The four books agree with each other at '+
    'the same rate as randomly generated tables, and when this same convergence was run on four random '+
    'books, 19% of those runs matched or beat the real books&rsquo; best score. Use the short list to cap '+
    'what you spend, not as a reason to bet more. The lift tag on each level is measured forward on your '+
    'own logged days &mdash; watch whether it holds above 1.00 over weeks.';
}

function renderChain(byState, windowDays){
  const el = document.getElementById('chainBody');
  /* These three rows read the same window as the rule sheet, and the series
     follow-up gets the same spent-check: a state whose 00x/05x/55x has already
     dropped is moved out of the watch list, exactly as with the pair rules. */
  const winA = (windowDays && windowDays.length) ? windowDays : [{ dayStates: byState || {} }];
  const NA = winA.length;
  const allFlat = [];
  winA.forEach((day, i) => {
    const ago = NA - 1 - i;
    Object.entries(day.dayStates || {}).forEach(([c, ns]) =>
      ns.forEach(n => allFlat.push({ n, c, ago })));
  });
  const S={},H={},T={};
  const put=(b,c,x)=>{(b[c]=b[c]||[]).push(x);};
  allFlat.forEach(x=>{
    if(isSeries(x.n)) put(S,x.c,x); if(isHundred(x.n)) put(H,x.c,x); if(isTriple(x.n)) put(T,x.c,x); });
  const winTxtA = NA>1 ? 'in '+NA+' days' : 'today';
  const row=(label,b)=>{
    const cs=Object.keys(b);
    return '<div style="margin-bottom:6px"><b style="font-size:11px;text-transform:uppercase;letter-spacing:.07em;color:var(--ink-soft)">'+label+'</b> '+
      (cs.length ? cs.map(c=>'<span class="chip">'+nm(c)+' '+b[c].map(x=>x.n).join('/')+
                     '<span class="ago">'+agoTxt(Math.min(...b[c].map(x=>x.ago)))+'</span></span>').join('')
                 : '<span class="empty">none '+winTxtA+'</span>')+'</div>';
  };
  let h = row('Series',S)+row('Hundreds (00x)',H)+row('Triples',T);

  /* series follow-up watch, with the spent-check */
  const isSeriesTgt = n => isHundred(n) || (n.indexOf('0')>=0 && n.indexOf('5')>=0) ||
                           (n.split('5').length-1) >= 2;
  const sOpen=[], sSpent=[];
  Object.entries(S).forEach(([c, xs])=>{
    const trig = xs.reduce((a,b)=> a.ago < b.ago ? a : b);
    const hits = allFlat.filter(x => x.c===c && isSeriesTgt(x.n));
    if(!hits.length) sOpen.push({c, ago:trig.ago});
    else sSpent.push({c, ago:trig.ago, hits,
      when: hits.some(x=>x.ago<trig.ago) ? 'after' :
            (hits.some(x=>x.ago===trig.ago) ? 'same day' : 'before')});
  });
  if(Object.keys(S).length){
    h += sOpen.length
      ? '<div class="baseline"><b class="openlbl">still open:</b> '+
        sOpen.sort((a,b)=>b.ago-a.ago).map(o=>'<span class="chip due">'+nm(o.c)+
          '<span class="ago">'+agoTxt(o.ago)+'</span></span>').join('')+
        ' &mdash; a series landed in these and no 00x / 05x / 55x has followed.</div>'
      : '<div class="baseline">Every state with a series has already dropped its 00x / 05x / 55x.</div>';
    if(sSpent.length)
      h += '<div class="baseline spentline"><b>already came:</b> '+
        sSpent.sort((a,b)=>b.ago-a.ago).map(sp=>'<span class="chip gone">'+nm(sp.c)+' &middot; '+
          sp.hits.slice(0,3).map(x=>x.n+' '+agoTxt(x.ago)).join(', ')+
          '<span class="whenTag">'+sp.when+'</span></span>').join('')+
        ' &mdash; the follow-up already dropped in these states. Move is done here.</div>';
  } else {
    h += '<div class="baseline">No series landed '+winTxtA+'.</div>';
  }

  /* ── rule-sheet rundown, read across the whole lookback window ──
     Each firing is tagged with how many days back it landed, and each rule is
     marked PENDING if its target has not landed in that state since it fired.
     A pending watch is the useful case: without this it vanished at midnight. */
  const win = (windowDays && windowDays.length) ? windowDays : [{ dayStates: byState || {} }];
  const N = win.length;
  const flat = [];   // every draw in the window, with state + days-ago + slot (m/e) + draw order k
  win.forEach((day, i) => {
    const ago = N - 1 - i;
    const SL = (day.date && DB.slots && DB.slots[day.date]) || { p3:{}, p4:{} };
    Object.entries(day.dayStates || {}).forEach(([c, ns]) => {
      const sl = sfSlotSplit(c, ns, (SL.p3||{})[c]);
      ns.forEach((n, k) => flat.push({ n, c, ago, s: sl[k], k }));
    });
    /* Pick 4 draws of the same day, for the Pick 4 rules (26, 29). Pick 3 rules never match them. */
    if(day.date){
      const p4 = {};
      (DB.p4log||[]).forEach(x => { if(x.date === day.date && x.state) (p4[x.state] = p4[x.state] || []).push(String(x.n)); });
      Object.entries(p4).forEach(([c, ns]) => { const sl = sfSlotSplit(c, ns, (SL.p4||{})[c]);
        ns.forEach((n, k) => flat.push({ n, c, ago, s: sl[k], k, g:4 })); });
    }
  });
  /* order of a draw in time across the window, so "after the trigger" can be judged within a day too */
  const tOrd = x => -x.ago*10 + (x.s === 'e' ? 5 : 0) + x.k*0.1;
  const lifts = ruleLifts();

  /* Rule 3 — make doubles out of the last drawing with 0, day to day and night to night */
  const r3 = { m:[], e:[] };
  const lastBy = {};
  flat.filter(x => !x.g).forEach(x => { const key = x.c+'|'+x.s;
    if(!lastBy[key] || tOrd(x) > tOrd(lastBy[key])) lastBy[key] = x; });
  Object.values(lastBy).forEach(x => r3[x.s === 'm' ? 'm' : 'e'].push(x));
  const r3chip = x => '<span class="chip" title="'+nm(x.c)+' '+(x.s==='m'?'midday':'evening')+' '+x.n+' '+agoTxt(x.ago)+'">'+
    nm(x.c)+' '+x.n+' &rarr; <b>'+(rule3Plays(x.n).join(' ') || 'all zeros &mdash; nothing to double')+'</b></span>';
  h += '<div class="sub-h">Rule 3 &mdash; doubles with 0 from the last draw</div>'+
    '<div class="prule-b"><b>next midday:</b> '+(r3.m.length ? capList(r3.m.sort((a,b)=>nm(a.c)<nm(b.c)?-1:1),'r3m',8,r3chip) : '<span class="empty">no midday draws yet</span>')+'</div>'+
    '<div class="prule-b"><b>next evening:</b> '+(r3.e.length ? capList(r3.e.sort((a,b)=>nm(a.c)<nm(b.c)?-1:1),'r3e',8,r3chip) : '<span class="empty">no evening draws yet</span>')+'</div>'+
    '<div style="font-size:11px;color:var(--ink-soft);margin:2px 0 8px">Each digit of that state&rsquo;s last midday (or evening) draw doubled with a 0, any order &mdash; 247 &rarr; 220 440 770 &mdash; to play in the same draw next time.</div>';

  const live = PAIR_RULES.map(rl => {
    const fired = flat.filter(x => ruleFires(x.n, rl) && (!rl.trigSlot || x.s === rl.trigSlot))
                      .sort((a, b) => a.ago - b.ago);
    /* Per state, sort into three buckets. The key correction: a target that landed
       BEFORE the trigger still counts as spent. The pairs in a rule travel as a
       group, so once the other side has dropped in that state the move is done —
       calling it "pending" sends you to pay for a number already gone. */
    const byC = {};
    fired.forEach(f => { if(!byC[f.c] || byC[f.c].ago < f.ago) byC[f.c] = f; });
    const pending = [], spent = [];
    Object.values(byC).forEach(f => {
      /* travel rules (35, 36) only count the partner number; rule 29 counts any state */
      const hits = flat.filter(x => (rl.anyState || x.c === f.c) && x !== f && ruleTargetFor(x.n, rl, f.n));
      if(!hits.length){ pending.push(f); return; }
      const after  = hits.filter(x => x.ago <  f.ago);            // landed since trigger
      const sameDay= hits.filter(x => x.ago === f.ago);
      const before = hits.filter(x => x.ago >  f.ago);            // landed before trigger
      spent.push({ ...f, after, sameDay, before,
                   when: after.length ? 'after' : (sameDay.length ? 'same day' : 'before') });
    });
    const repeats = Object.entries(byC).map(([c]) =>
      ({ c, k: fired.filter(f => f.c === c).length })).filter(x => x.k > 1);
    return { rl, fired, pending, spent, repeats };
  }).filter(x => x.fired.length);
  const nPend = live.filter(x => x.pending.length).length;
  const nSpent = live.reduce((a,x) => a + x.spent.length, 0);
  h += '<div class="sub-h">Rule sheet &mdash; '+live.length+' of '+PAIR_RULES.length+
       ' triggered in '+N+' day'+(N>1?'s':'')+
       (nPend ? ', <span class="pendcount">'+nPend+' with open states</span>' : '')+
       (nSpent ? ' <span class="spentcount">'+nSpent+' already came</span>' : '')+
       (live.length ? '<span class="rule-all">'+
         '<a href="#" onclick="setAllRules(true);return false;">open all</a> &middot; '+
         '<a href="#" onclick="setAllRules(false);return false;">close all</a></span>' : '')+
       '</div>';
  if(live.length){
    // pending rules first — those are the live watches
    live.sort((a,b) => (b.pending.length?1:0)-(a.pending.length?1:0) || a.rl.id-b.rl.id);
    h += live.map(({rl, fired, pending, spent, repeats}) => {
      const already = flat.filter(x => fired.some(f => x !== f && ruleTargetFor(x.n, rl, f.n)));
      const L = lifts[rl.id];
      const liftTxt = L && L.exp >= 3
        ? '<span class="rlift'+(L.lift>=1.25?' up':(L.lift<=0.8?' dn':''))+'">lift '+L.lift.toFixed(2)+'</span>'
        : '<span class="rlift">no data yet</span>';
      const open = !!RULE_OPEN[rl.id];
      return '<div class="prule fired'+(open?' open':'')+'" id="prule-'+rl.id+'">'+
        '<div class="prule-h" onclick="toggleRule('+rl.id+')">'+
          '<span class="rcaret">&#9660;</span>'+
          '<span class="rname">Rule '+rl.id+' &mdash; '+rl.trigTxt+(rl.dyn?' travels with ':' brings ')+rl.tgtTxt+
            (rl.orig ? '' : ' <span class="rnew">new</span>')+(rl.wide ? ' <span class="rwide">wide</span>' : '')+'</span>'+
          '<span class="rtags">'+
          (pending.length ? '<span class="rpend">'+pending.length+' open</span>' : '')+
          (spent.length ? '<span class="rspent">'+spent.length+' came</span>' : '')+
          '<span class="rcount">'+fired.length+'&times;</span>'+
          '<span class="rcov">'+(rl.cov*100).toFixed(0)+'%</span>'+liftTxt+'</span>'+
        '</div>'+
        '<div class="prule-body">'+
          '<div class="prule-b"><b>fired:</b> '+
            capList(fired, 'fired'+rl.id, 10, x => '<span class="chip">'+x.n+' '+nm(x.c)+
              '<span class="ago">'+agoTxt(x.ago)+'</span></span>')+'</div>'+
          (pending.length
            ? '<div class="prule-b"><b>still open:</b> '+
                pending.sort((a,b)=>b.ago-a.ago).map(f => '<span class="chip due">'+nm(f.c)+
                  '<span class="ago">'+agoTxt(f.ago)+'</span></span>').join('')+
                ' <span style="opacity:.6;font-size:11px">&mdash; no '+rl.tgtTxt+
                ' anywhere in these states this window</span></div>'
            : '')+
          (spent.length
            ? '<div class="prule-b spent"><b>already came:</b> '+
                spent.sort((a,b)=>b.ago-a.ago).map(sp => {
                  const ns = [...sp.after, ...sp.sameDay, ...sp.before];
                  const extra = ns.length>3 ? ' +'+(ns.length-3)+' more' : '';
                  return '<span class="chip gone">'+nm(sp.c)+' &middot; '+
                    ns.slice(0,3).map(x => x.n+' '+agoTxt(x.ago)).join(', ')+extra+
                    '<span class="whenTag">'+sp.when+'</span></span>';
                }).join('')+
                ' <span style="opacity:.65;font-size:11px">&mdash; '+rl.tgtTxt+
                ' already dropped in these states, before or after the trigger. '+
                'The move is done here.</span></div>'
            : '')+
          (repeats.length
            ? '<div class="prule-b"><b>repeats:</b> '+repeats.map(r=>'<span class="chip">'+
                nm(r.c)+' &times;'+r.k+'</span>').join('')+
              ' <span style="opacity:.6;font-size:11px">rare, but at the rate rotation predicts</span></div>'
            : '')+
          (already.length ? '<div class="prule-b" style="opacity:.6"><b>target already in:</b> '+
            capList([...new Set(already.map(x=>x.n))], 'alr'+rl.id, 8,
              n => '<span class="chip">'+n+'</span>')+'</div>' : '')+
        '</div>'+
      '</div>';
    }).join('');
  } else {
    h += '<div class="baseline">No rule triggered today.</div>';
  }
  h += '<div class="baseline">All 36 rules from the sheet are here (rule 1 is inside rule 21; rule 3 has its own row above). '+
       'The percentage on each rule is how much of the 1000-number field its target covers. '+
       'Rules marked <b>wide</b> (&ldquo;brings a double&rdquo;, &ldquo;look for 3, 4 or 8&rdquo;) cover over a fifth of all numbers, '+
       'so they land often whether or not the rule is working &mdash; read their &ldquo;came&rdquo; counts with that in mind. '+
       '<b>False trip</b> = a double plus its mirror digit (0&harr;5, 1&harr;6, 2&harr;7, 3&harr;8, 4&harr;9): 116 227 338 449 550 661 772 883 994 005, any order. '+
       '<b>Lift</b> is measured forward on your own logged days &mdash; 1.00 means the rule is doing no better than '+
       'its target size predicts. It needs weeks before it means much. '+
       '<b>Still open</b> means the target has not landed in that state anywhere in the window. '+
       '<b>Already came</b> means it did land there &mdash; before or after the trigger, with the number and day shown. '+
       'Order is recorded but both count as spent: once the other side of the rule has dropped in a state, '+
       'chasing it costs money for a number that is already gone. <b>Repeats</b> are shown because you asked, but a state '+
       'firing twice is not a stronger signal: repeat rates in your own data match what rotation predicts '+
       '(pair 25 recurred in 4 of 41 states over three days against 13% expected). Use the day window '+
       'selector at the top to widen or narrow all of this.</div>';
  el.innerHTML = h;
}

/* ══════════ SCOREKEEPING (tucked away, but kept) ══════════ */
function almanacBacktest(){ return histMemo('almanacBacktest', almanacBacktestRun); }
function almanacBacktestRun(){
  const v = DB.dayLog.filter(e=>e.dayStates);
  let days=0, cHit=0, cN=0, cExp=0, pHit=0, pN=0, pExp=0, wHit=0, wN=0, wExp=0;
  const K = lookback();
  for(let d=0; d<v.length-1; d++){
    const an = almanacAnalysis(pooledDays(K, d));
    const next = v[d+1].draws;
    const nextKeys = new Set(next.map(keyOf));
    const cover = n => boxMode() ? perms(n).length/1000 : 1/1000;
    const tally = (list, get) => {
      let hit=0, exp=0;
      const uniq = [...new Set(list.map(get))];
      /* AUDIT FIX: hit is 0/1 per flagged number, so chance must be the
         probability of AT LEAST ONE landing — 1-(1-p)^N — not the expected
         COUNT N*p. With ~80 pooled draws a day the old baseline overcharged
         by ~21%, printing lift 0.79 for a table that is actually at ~0.97. */
      uniq.forEach(n => { if(nextKeys.has(keyOf(n))) hit++;
        exp += 1 - Math.pow(1 - cover(n), next.length); });
      return [hit, uniq.length, exp];
    };
    let r;
    r = tally(an.confirmed, x=>x.key);  cHit+=r[0]; cN+=r[1]; cExp+=r[2];
    r = tally(an.partial,   x=>x.want); pHit+=r[0]; pN+=r[1]; pExp+=r[2];
    r = tally(an.watch.flatMap(x=>x.rel), x=>x); wHit+=r[0]; wN+=r[1]; wExp+=r[2];
    days++;
  }
  return {days, c:{hit:cHit,n:cN,exp:cExp}, p:{hit:pHit,n:pN,exp:pExp}, w:{hit:wHit,n:wN,exp:wExp}};
}
function renderAlmanacScore(){
  const el = document.getElementById('almanacScore');
  const b = almanacBacktest();
  if(b.days < 1){ el.innerHTML='<div class="sub-h">Almanac track record</div>'+
    '<div class="baseline">Add a second day to start scoring the table against what actually falls.</div>'; return; }
  const line = (label, o) => {
    const lift = o.exp>0 ? (o.hit/o.exp) : 0;
    return '<tr><td>'+label+'</td><td>'+o.n+'</td><td>'+o.hit+'</td><td>'+o.exp.toFixed(1)+
           '</td><td><b>'+(o.exp>0?lift.toFixed(2)+'&times;':'&mdash;')+'</b></td></tr>';
  };
  el.innerHTML = '<div class="sub-h">Almanac track record &mdash; '+b.days+' scored transition'+(b.days>1?'s':'')+', '+lookback()+'d window</div>'+
    '<table class="tbl"><tr><th>signal</th><th>flagged</th><th>hit</th><th>chance</th><th>lift</th></tr>'+
    line('Both relatives', b.c) + line('One relative', b.p) + line('Plain watch', b.w) + '</table>'+
    '<div class="baseline">Lift is hits divided by what random chance predicts for the same number of flags. '+
    '1.00&times; means the table is doing nothing beyond covering ground. A few days will swing wildly; '+
    'a few weeks starts to mean something.</div>';
}
/* The two track records sit in the closed History section and are the slowest
   things on the page; score them only once it is opened. */
function renderHistoryScores(){
  const box = document.getElementById('meter').closest('details');
  if(box && !box.open){
    if(!box.dataset.lazy){ box.dataset.lazy = '1';
      box.addEventListener('toggle', () => { if(box.open && DB.dayLog.length) renderHistoryScores(); }); }
    return;
  }
  renderMeter();
  renderAlmanacScore();
}
function renderMeter(){
  const el = document.getElementById('meter');
  const N = parseInt(document.getElementById('topN').value,10)||5;
  const v = DB.dayLog.filter(e=>e.dayStates);
  if(v.length < 3){ el.innerHTML='<div class="sub-h">Shortlist track record</div>'+
    '<div class="baseline">Needs at least 3 logged days.</div>'; return; }
  const { staked, won, hits, exp } = histMemo('meter', () => {
  let staked=0, won=0, hits=0, exp=0;
  const K = lookback();
  /* AUDIT FIX: the old meter paid $80 whenever a pick landed ANYWHERE in the
     country while charging $1 total — but a hit in Georgia pays nothing unless
     you bought the ticket in Georgia. That printed fantasy profit (+$2,215 on
     a real 22-day log whose honest number is -66%). Honest accounting: $1 on
     each pick in EVERY next-day draw, paid only where a ticket was. */
  for(let d=0; d<v.length-1; d++){
    const pl = pooledDays(K, d);
    const an = almanacAnalysis(pl);
    const picks = scoreBoard(pl, an).slice(0,N).map(p=>p.num);
    const next = v[d+1].draws;
    staked += picks.length * next.length;
    picks.forEach(p=>{
      const matches = next.filter(x => keyOf(x) === keyOf(p)).length;
      hits += matches; won += matches * (boxMode()?80:500);
      exp += next.length * (boxMode()?perms(p).length:1)/1000;
    });
  }
  return { staked, won, hits, exp };
  });
  const net = won - staked, roi = staked ? net/staked : 0;
  const money = x => (x<0?'-$':'$') + Math.abs(Math.round(x)).toLocaleString();
  el.innerHTML = '<div class="sub-h">Shortlist track record &mdash; top '+N+', $1 on each pick in every draw</div>'+
    '<div class="stat">'+
    '<div><div class="v">'+hits+'</div><div class="l">winning tickets</div></div>'+
    '<div><div class="v">'+exp.toFixed(1)+'</div><div class="l">chance</div></div>'+
    '<div><div class="v">'+money(staked)+'</div><div class="l">staked</div></div>'+
    '<div><div class="v" style="color:'+(net<0?'var(--pen)':'#1D6B3F')+'">'+money(net)+'</div><div class="l">net '+(roi*100).toFixed(0)+'%</div></div>'+
    '</div><div class="baseline">Payout '+(boxMode()?'$80 box':'$500 straight')+', $1 per pick per draw &mdash; a hit only pays '+
    'in the state where the ticket was bought, so the stake covers every draw the picks were exposed to. '+
    'The game&rsquo;s structure alone gives '+(boxMode()?'-52%':'-50%')+' expected ROI; beating that needs lift, not luck. '+
    'Covers every logged day except the most recent, which has nothing to score against yet.</div>';
}
function renderPairAccuracy(){
  const el = document.getElementById('pairAccuracy');
  if(DB.dayLog.length < 2){ el.innerHTML=''; return; }
  let tot=0, hit=0, base=0, t=0;
  for(let d=0; d<DB.dayLog.length-1; d++){
    const ap = new Set(DB.dayLog[d].appeared);
    const miss = ALL_PAIRS.filter(p=>!ap.has(p));
    const next = new Set(DB.dayLog[d+1].appeared);
    tot += miss.length; hit += miss.filter(p=>next.has(p)).length;
    base += DB.dayLog[d+1].appeared.length/55; t++;
  }
  const rate = tot?hit/tot:0, b = t?base/t:0;
  el.innerHTML = '<div class="sub-h">Missing-pair rule &mdash; '+t+' transition'+(t>1?'s':'')+'</div>'+
    '<div class="baseline">Pairs missing one day showed the next day <b>'+(rate*100).toFixed(0)+'%</b> of the time, '+
    'against a <b>'+(b*100).toFixed(0)+'%</b> baseline &mdash; lift <b>'+(b>0?(rate/b).toFixed(2):'—')+'&times;</b>.</div>';
}

/* ══════════ STATE-SPECIFIC VIEW ══════════
   The question: when a signal fires IN a state, does THAT state's next draw
   hit the signal's targets more often than the targets' field coverage
   predicts — and more often than every other state's draws do?
   Same discipline as everything else here: forward-only (day-d signals scored
   on day d+1), every figure against a coverage baseline, controls before
   anything is called a signal. Signals are generated from ONE day of one
   state's draws — the 1-day window is the only setting that stayed selective
   in pooled testing. Prior pooled results were chance everywhere (665 draws,
   lifts 0.89–1.24, random books beating the real ones 12–44% of the time),
   so the expected outcome here is same-state ≈ cross-state ≈ 1.00. */

const PERM_COUNT = (()=>{ const m={}; for(let i=0;i<1000;i++){
  const k=sortD(String(i).padStart(3,'0')); m[k]=(m[k]||0)+1; } return m; })();
const setCov = set => { let c=0; set.forEach(k=>c += PERM_COUNT[k]||0); return c/1000; };

const RULECOV_MEMO = {};
function rulesCov(fired){
  const sig = fired.map(r=>r.id).join(',');
  if(RULECOV_MEMO[sig] !== undefined) return RULECOV_MEMO[sig];
  let c=0;
  for(let i=0;i<1000;i++){ const n=String(i).padStart(3,'0');
    if(fired.some(rl=>ruleTarget(n,rl))) c++; }
  return RULECOV_MEMO[sig] = c/1000;
}

function realBooks(){ return { A16:ALMANAC, A17:ALMANAC17, FU:FOLLOWUPS, REL:RELATIVES, A25:ALMANAC25, RS:BOLD_REL }; }

/* Signal families. Each gen(draws) reads ONE state's draws for ONE day and
   returns null (nothing fired) or {pred, cov}: a match test over BOXED keys
   for next-day draws plus the exact share of the 1000-number field it covers.
   (Every predicate here is order-independent, so testing the boxed key is
   exact, not an approximation.) Books are injected so the random-book
   control can swap them. */
function famDefs(bk){
  bk = bk || realBooks();
  const wrap = s => (s && s.size) ? { pred:k=>s.has(k), cov:setCov(s) } : null;
  const boxSet = (draws, fn) => { const s=new Set();
    draws.forEach(n => fn(n).forEach(t => s.add(sortD(t)))); return s; };
  const convCnt = draws => {
    const t = { a:new Set(), b:new Set(), f:new Set(), r:new Set() };
    draws.forEach(n => {
      (bk.A16[n]||[]).forEach(x=>t.a.add(sortD(x)));
      (bk.A17[n]||[]).forEach(x=>t.b.add(sortD(x)));
      const f=bk.FU[n]; if(f) t.f.add(sortD(f));
      const r=bk.REL[sortD(n)]; if(r) t.r.add(sortD(r));
    });
    const c={}; Object.values(t).forEach(s=>s.forEach(k=>c[k]=(c[k]||0)+1));
    return c;
  };
  return [
    { id:'a16',  name:"Almanac '16 relatives", book:true,
      gen:d=>wrap(boxSet(d, n=>bk.A16[n]||[])) },
    { id:'a17',  name:"Almanac '17 relatives", book:true,
      gen:d=>wrap(boxSet(d, n=>bk.A17[n]||[])) },
    { id:'rs',   name:"Red Side relatives (lookup-only)", book:true,
      gen:d=>wrap(boxSet(d, n=>(bk.RS||{})[sortD(n)]||[])) },
    { id:'a25',  name:"Grandma 2025 follow-ups (lookup-only)", book:true,
      gen:d=>wrap(boxSet(d, n=>(bk.A25||{})[n]||[])) },
    { id:'fu',   name:'Follow Ups', book:true,
      gen:d=>wrap(boxSet(d, n=>bk.FU[n]?[bk.FU[n]]:[])) },
    { id:'rel',  name:'Relative Numbers', book:true,
      gen:d=>wrap(boxSet(d, n=>bk.REL[sortD(n)]?[bk.REL[sortD(n)]]:[])) },
    { id:'conv2', name:'2+ books agree', book:true,
      gen:d=>{ const c=convCnt(d);
        return wrap(new Set(Object.keys(c).filter(k=>c[k]>=2))); } },
    { id:'conv4', name:'4 books agree', book:true,
      gen:d=>{ const c=convCnt(d);
        return wrap(new Set(Object.keys(c).filter(k=>c[k]>=4))); } },
    { id:'rules', name:'Pair rules (original 15)', book:false,
      gen:d=>{ const fired = PAIR_RULES.filter(rl=>rl.orig && d.some(n=>ruleFires(n,rl)));
        if(!fired.length) return null;
        return { pred:k=>fired.some(rl=>ruleTarget(k,rl)), cov:rulesCov(fired) }; } },
    { id:'series', name:'Series brings', book:false,
      gen:d=>{ const s=new Set();
        d.forEach(n=>{ if(isSeries(n)){ const e=SERIES_BRINGS[sortD(n)];
          if(e) e.dblBox.forEach(x=>s.add(x)); }});
        return wrap(s); } }
  ];
}

/* Precompute, per transition, every state's fired targets — so the label
   shuffle can re-score 200 times without regenerating anything. */
function statePre(defs){
  const v = DB.dayLog.filter(e=>e.dayStates);
  const pre=[];
  for(let d=0; d<v.length-1; d++){
    const tgt={};
    Object.entries(v[d].dayStates).forEach(([c,draws])=>{
      const fm={};
      defs.forEach(f=>{ const g=f.gen(draws); if(g) fm[f.id]=g; });
      if(Object.keys(fm).length) tgt[c]=fm;
    });
    pre.push({ tgt, to: v[d+1].dayStates });
  }
  return pre;
}

/* Compile the precomputed targets into per-transition hit tables: for every
   fired (state, family), the hit count against EVERY state's next-day list.
   Cross-state totals are shuffle-invariant, so the 200-shuffle control
   reduces to table lookups instead of re-scoring draws. */
function stateComp(pre){
  return pre.map(p=>{
    const codes = Object.keys(p.to);
    const boxed = codes.map(c=>p.to[c].map(sortD));
    const nDraw = codes.map(c=>p.to[c].length);
    const fires = [];
    Object.entries(p.tgt).forEach(([c,fams])=>{
      const idx = codes.indexOf(c);
      Object.entries(fams).forEach(([fid,g])=>{
        const h = boxed.map(bl=>{ let x=0; bl.forEach(k=>{ if(g.pred(k)) x++; }); return x; });
        const exp = nDraw.map(n=>n*g.cov);
        fires.push({ fid, idx,
          h, exp,
          totH: h.reduce((a,b)=>a+b,0),
          totExp: exp.reduce((a,b)=>a+b,0),
          cov: g.cov });
      });
    });
    return { codes, fires };
  });
}

/* Score a compiled table. Same = the state that fired; cross = everyone else.
   permute=true re-deals the next-day result lists to random states. */
function scoreComp(comp, defs, permute, wantStates){
  const zero=()=>({hits:0,exp:0,n:0,covSum:0});
  const byFam={}; defs.forEach(f=>byFam[f.id]={same:zero(),cross:zero()});
  const byState = wantStates ? {} : null;
  comp.forEach(t=>{
    let map=null;
    if(permute){ map = shuffleArr(t.codes.map((_,i)=>i)); }
    t.fires.forEach(f=>{
      const fam = byFam[f.fid]; if(!fam) return;
      const idx = f.idx < 0 ? -1 : (map ? map[f.idx] : f.idx);
      const sH = idx<0 ? 0 : f.h[idx], sE = idx<0 ? 0 : f.exp[idx];
      fam.same.hits += sH; fam.same.exp += sE;
      if(idx>=0){ fam.same.n++; fam.same.covSum += f.cov; }
      fam.cross.hits += f.totH - sH; fam.cross.exp += f.totExp - sE;
      if(byState && !permute && f.idx>=0){
        const c=t.codes[f.idx];
        const s=(byState[c]=byState[c]||{hits:0,exp:0,n:0});
        s.hits+=sH; s.exp+=sE; s.n++;
      }
    });
  });
  return { byFam, byState };
}

function stateMatched(){ return histMemo('stateMatched', stateMatchedRun); }
function stateMatchedRun(){
  const defs = famDefs();
  const comp = stateComp(statePre(defs));
  const sc = scoreComp(comp, defs, false, true);
  return { defs, comp, byFam:sc.byFam, byState:sc.byState };
}

/* Lean same-state-only scorer for the random-book control — no cross tables. */
function sameOnlyScore(defs){
  const v = DB.dayLog.filter(e=>e.dayStates);
  const out={}; defs.forEach(f=>out[f.id]={hits:0,exp:0});
  for(let d=0; d<v.length-1; d++){
    const to = v[d+1].dayStates;
    Object.entries(v[d].dayStates).forEach(([c,draws])=>{
      const nxt = to[c]; if(!nxt || !nxt.length) return;
      const nb = nxt.map(sortD);
      defs.forEach(f=>{
        const g = f.gen(draws); if(!g) return;
        let h=0; nb.forEach(k=>{ if(g.pred(k)) h++; });
        out[f.id].hits+=h; out[f.id].exp+=nxt.length*g.cov;
      });
    });
  }
  return out;
}

/* Δ statistic: same-state lift minus cross-state lift, per family + combined */
function deltaStat(byFam){
  const o={}; let sh=0,se=0,ch=0,ce=0;
  Object.entries(byFam).forEach(([id,f])=>{
    sh+=f.same.hits; se+=f.same.exp; ch+=f.cross.hits; ce+=f.cross.exp;
    o[id] = (f.same.exp>0 && f.cross.exp>0)
      ? f.same.hits/f.same.exp - f.cross.hits/f.cross.exp : null;
  });
  o.all = (se>0 && ce>0) ? sh/se - ch/ce : null;
  return o;
}

const shuffleArr = a => { for(let i=a.length-1;i>0;i--){
  const j=Math.floor(Math.random()*(i+1)); const t=a[i]; a[i]=a[j]; a[j]=t; } return a; };

/* Control 1 — label shuffle. If state identity carries no information,
   handing each next-day result set to a random state should produce a Δ this
   big about as often as not. Reports the share of shuffles ≥ the real Δ. */
function permControl(comp, defs, realDelta, runs){
  const beat={}, cnt={};
  Object.keys(realDelta).forEach(k=>{ beat[k]=0; cnt[k]=0; });
  for(let r=0;r<runs;r++){
    const sc = scoreComp(comp, defs, true, false);
    const d = deltaStat(sc.byFam);
    Object.keys(realDelta).forEach(k=>{
      if(realDelta[k]==null || d[k]==null) return;
      cnt[k]++; if(d[k] >= realDelta[k]) beat[k]++;
    });
  }
  const out={};
  Object.keys(realDelta).forEach(k=>{
    out[k] = cnt[k] ? Math.round(100*beat[k]/cnt[k]) : null; });
  return out;
}

/* Control 2 — random books. The same state-matched machinery with the four
   books replaced by randomly generated tables of identical shape. Reports the
   share of random runs whose same-state lift matches or beats the real one.
   (Rules and series have no book to randomize — the label shuffle is their
   control, and the pooled rule sheet already carries their forward lifts.) */
function randControl(realByFam, runs){
  const bookIds = famDefs().filter(f=>f.book).map(f=>f.id);
  const beat={}, cnt={};
  bookIds.forEach(id=>{ beat[id]=0; cnt[id]=0; });
  const r3=()=>String(Math.floor(Math.random()*1000)).padStart(3,'0');
  for(let r=0;r<runs;r++){
    const A={},B={},F={},R={},C={};
    for(let i=0;i<1000;i++){ const k=String(i).padStart(3,'0');
      A[k]=[r3(),r3()]; B[k]=[r3(),r3()]; F[k]=r3(); C[k]=[r3(),r3()]; }
    Object.keys(RELATIVES).forEach(k=>{ R[k]=r3(); });
    const S={}; Object.entries(BOLD_REL).forEach(([k,l])=>{ S[k]=l.map(()=>r3()); });
    const defs = famDefs({A16:A,A17:B,FU:F,REL:R,A25:C,RS:S}).filter(f=>f.book);
    const sc = sameOnlyScore(defs);
    bookIds.forEach(id=>{
      const rf=realByFam[id], ff=sc[id];
      if(!rf || rf.same.exp<=0 || !ff || ff.exp<=0) return;
      cnt[id]++;
      if(ff.hits/ff.exp >= rf.same.hits/rf.same.exp) beat[id]++;
    });
  }
  const out={};
  bookIds.forEach(id=>{ out[id]=cnt[id]?Math.round(100*beat[id]/cnt[id]):null; });
  return out;
}

function runStateControls(){
  const st=document.getElementById('stCtlStatus');
  const v = DB.dayLog.filter(e=>e.dayStates);
  if(v.length < 2){ st.className='status warn';
    st.textContent='needs at least 2 logged days'; return; }
  st.className='status'; st.textContent='running 200 shuffles + 200 random books…';
  setTimeout(()=>{
    const m = stateMatched();
    const delta = deltaStat(m.byFam);
    const perm = permControl(m.comp, m.defs, delta, 200);
    const rand = randControl(m.byFam, 200);
    DB.stateCtl = { at: DB.dayLog.length, perm, rand };
    save();
    st.textContent='';
    render();
  }, 30);
}

/* lift cell: honest about thin data — below minExp it shows the raw count
   instead of a lift figure that would just be noise dressed up */
function stLift(hits, exp, minExp){
  if(exp <= 0) return '<span class="rlift">&mdash;</span>';
  if(exp < minExp)
    return '<span class="rlift">thin &middot; '+hits+' vs '+exp.toFixed(1)+'</span>';
  const l = hits/exp;
  return '<span class="rlift'+(l>=1.25?' up':(l<=0.8?' dn':''))+'">'+l.toFixed(2)+'</span>';
}

/* Live watch panel for one state: what fired HERE, what is still open HERE. */
function stateLiveHTML(S, m){
  const K = lookback();
  const v = DB.dayLog.filter(e=>e.dayStates);
  const win = v.slice(-K);
  const evs=[];
  win.forEach((day,i)=>{
    const ago=win.length-1-i;
    (day.dayStates[S]||[]).forEach(n=>evs.push({n,ago}));
  });
  let h = '<div class="sub-h">'+nm(S)+' &mdash; last '+win.length+' day'+(win.length>1?'s':'')+'</div>';
  if(!evs.length)
    return h+'<div class="empty">No '+nm(S)+' draws in this window. Widen the day window or add days.</div>';
  h += '<div>'+evs.sort((a,b)=>a.ago-b.ago).map(e=>
    '<span class="chip">'+e.n+'<span class="ago">'+agoTxt(e.ago)+'</span></span>').join('')+'</div>';

  /* book targets from this state's own draws, open vs already-came in state
     (shared with the State Specific Numbers panel so the two never disagree) */
  const st=stateTargets(S, win);
  const open=Object.entries(st.open).map(([k,o])=>({k,o}));
  const came=Object.entries(st.came).map(([k,o])=>({k,o}));
  open.sort((a,b)=>b.o.books.size-a.o.books.size || (a.k<b.k?-1:1));
  came.sort((a,b)=>(a.k<b.k?-1:1));
  const chip=(x,cls)=>'<span class="chip'+cls+'" title="'+[...x.o.books].join(', ')+
    (x.o.books.size>1?' — '+x.o.books.size+' books':'')+'">'+x.k+
    (x.o.books.size>1?'<span class="ago">&times;'+x.o.books.size+'</span>':'')+'</span>';
  h += '<div class="sub-h">Book targets from '+nm(S)+'&rsquo;s own draws (boxed)</div>';
  h += open.length
    ? '<div><b class="openlbl" style="font-size:10px;text-transform:uppercase;letter-spacing:.06em">still open here:</b> '+
      capList(open,'stOpen'+S,20,x=>chip(x, x.o.books.size>1?' due':''))+'</div>'
    : '<div class="empty" style="font-size:12px">every pointed-at number already landed here.</div>';
  if(came.length)
    h += '<div style="margin-top:4px"><b style="font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:var(--ink-soft)">already came here:</b> '+
      capList(came,'stCame'+S,12,x=>chip(x,' gone'))+'</div>';

  /* pair rules fired in this state */
  const fired = PAIR_RULES.map(rl=>{
    const f=evs.filter(e=>ruleFires(e.n,rl));
    if(!f.length) return null;
    const trig=f.reduce((a,b)=>a.ago<b.ago?a:b);
    const hits=evs.filter(e=>e!==trig && ruleTargetFor(e.n,rl,trig.n));
    return {rl,trig,hits};
  }).filter(Boolean);
  if(fired.length){
    h += '<div class="sub-h">Rules fired in '+nm(S)+'</div><div>'+fired.map(x=>
      '<span class="chip'+(x.hits.length?' gone':' due')+'" title="'+x.rl.trigTxt+' brings '+x.rl.tgtTxt+'">'+
      'R'+x.rl.id+' &middot; '+x.trig.n+'<span class="ago">'+agoTxt(x.trig.ago)+'</span>'+
      (x.hits.length?' &#10005;':' open')+'</span>').join('')+
      '</div><div style="font-size:10px;color:var(--ink-soft);margin-top:2px">open = target pair not yet in '+nm(S)+
      ' this window &middot; &#10005; = target already dropped here (before or after the trigger &mdash; both count as spent)</div>';
  }

  /* series in this state, with the drop-and-reset rule scoped to the state */
  const sevs=[]; v.forEach((day,i)=>{ const ago=v.length-1-i;
    (day.dayStates[S]||[]).forEach(n=>sevs.push({n,ago})); });
  const srows=[];
  Object.values(SERIES_BRINGS).forEach(e=>{
    const drops=sevs.filter(x=>sortD(x.n)===sortD(e.series));
    const lastDrop=drops.length?Math.min(...drops.map(x=>x.ago)):Infinity;
    const led=[];
    e.dblBox.forEach((db,i)=>{
      const hs=sevs.filter(x=>sortD(x.n)===db && x.ago<lastDrop);
      if(hs.length) led.push({d:e.dbls[i],ago:Math.min(...hs.map(x=>x.ago))});
    });
    if(lastDrop===0) srows.push({e,tag:'dropped today &mdash; reset'});
    else if(led.length) srows.push({e,tag:led.length+'/'+e.dblBox.length+' doubles in'+
      (isFinite(lastDrop)?' since its last '+nm(S)+' drop':''), led});
  });
  if(srows.length){
    h += '<div class="sub-h">Series in '+nm(S)+' (state-scoped reset)</div><div>'+
      srows.map(r=>'<span class="chip">'+r.e.series+'<span class="ago">'+r.tag+'</span></span>').join('')+'</div>';
  }
  return h;
}

function renderStateView(){
  const selEl=document.getElementById('stSel');
  const liveEl=document.getElementById('stLive');
  const scoreEl=document.getElementById('stScore');
  const perEl=document.getElementById('stPerState');
  const cntEl=document.getElementById('stCount');
  const baseEl=document.getElementById('stBase');
  const v = DB.dayLog.filter(e=>e.dayStates);
  const states=[...new Set(v.reduce((a,d)=>a.concat(Object.keys(d.dayStates)),[]))]
    .sort((a,b)=>nm(a)<nm(b)?-1:1);
  const have=[...selEl.options].map(o=>o.value).join();
  if(have !== ['',...states].join()){
    const cur=selEl.value;
    selEl.innerHTML='<option value="">&mdash; overview &mdash;</option>'+
      states.map(c=>'<option value="'+c+'">'+nm(c)+'</option>').join('');
    if(states.indexOf(cur)>=0) selEl.value=cur;
  }
  if(v.length<2){
    cntEl.textContent = v.length ? '1 day logged — needs 2 to score' : '';
    liveEl.innerHTML = v.length && selEl.value ? stateLiveHTML(selEl.value, null)
      : '<div class="empty">'+(v.length?'Pick a state to see its live signals. Scoring starts at 2 logged days.':'Add a day to begin.')+'</div>';
    scoreEl.innerHTML=''; perEl.innerHTML=''; baseEl.innerHTML='';
    return;
  }
  const m = stateMatched();
  const delta = deltaStat(m.byFam);
  const ctl = (DB.stateCtl && DB.stateCtl.at === DB.dayLog.length) ? DB.stateCtl : null;
  const stale = DB.stateCtl && DB.stateCtl.at !== DB.dayLog.length;
  cntEl.textContent = states.length+' states · '+(v.length-1)+' scored transition'+(v.length-1>1?'s':'');

  liveEl.innerHTML = selEl.value ? stateLiveHTML(selEl.value, m)
    : '<div class="empty" style="font-size:12px">Pick a state above to see its live signals; the scorecard below covers all of them.</div>';

  /* scorecard: every family, same-state vs cross-state */
  const MIN=5;
  const famRow = f => {
    const s=m.byFam[f.id], d=delta[f.id];
    const dTxt = d===null ? '&mdash;'
      : '<b style="color:'+(d>0?'#1D6B3F':'var(--pen)')+'">'+(d>0?'+':'')+d.toFixed(2)+'</b>';
    const permTxt = ctl && ctl.perm[f.id]!==null && ctl.perm[f.id]!==undefined ? ctl.perm[f.id]+'%' : '&mdash;';
    const randTxt = ctl && f.book && ctl.rand[f.id]!==null && ctl.rand[f.id]!==undefined ? ctl.rand[f.id]+'%'
      : (f.book?'&mdash;':'n/a');
    return '<tr><td>'+f.name+'</td><td>'+s.same.n+'</td>'+
      '<td>'+(s.same.n?((s.same.covSum/s.same.n)*100).toFixed(0)+'%':'&mdash;')+'</td>'+
      '<td>'+s.same.hits+'</td><td>'+s.same.exp.toFixed(1)+'</td>'+
      '<td>'+stLift(s.same.hits,s.same.exp,MIN)+'</td>'+
      '<td>'+stLift(s.cross.hits,s.cross.exp,MIN)+'</td>'+
      '<td>'+dTxt+'</td><td>'+permTxt+'</td><td>'+randTxt+'</td></tr>';
  };
  let allS={hits:0,exp:0}, allC={hits:0,exp:0};
  Object.values(m.byFam).forEach(f=>{ allS.hits+=f.same.hits; allS.exp+=f.same.exp;
    allC.hits+=f.cross.hits; allC.exp+=f.cross.exp; });
  const dAll = delta.all;
  scoreEl.innerHTML =
    '<div class="sub-h">State-matched track record &mdash; signal fired in a state, scored on that state&rsquo;s next day</div>'+
    '<div style="overflow-x:auto"><table class="tbl"><tr><th>signal</th><th>fired</th><th>avg field</th>'+
    '<th>hits</th><th>chance</th><th>same-state</th><th>cross-state</th><th>&Delta;</th>'+
    '<th title="share of 200 label shuffles matching or beating the real Δ">shuffle &ge;</th>'+
    '<th title="share of 200 random-book runs matching or beating the real same-state lift">random &ge;</th></tr>'+
    m.defs.map(famRow).join('')+
    '<tr style="border-top:2px solid var(--rule)"><td><b>All families</b></td><td></td><td></td>'+
    '<td>'+allS.hits+'</td><td>'+allS.exp.toFixed(1)+'</td>'+
    '<td>'+stLift(allS.hits,allS.exp,MIN)+'</td><td>'+stLift(allC.hits,allC.exp,MIN)+'</td>'+
    '<td>'+(dAll===null?'&mdash;':'<b style="color:'+(dAll>0?'#1D6B3F':'var(--pen)')+'">'+(dAll>0?'+':'')+dAll.toFixed(2)+'</b>')+'</td>'+
    '<td>'+(ctl && ctl.perm.all!==null && ctl.perm.all!==undefined?ctl.perm.all+'%':'&mdash;')+'</td><td></td></tr>'+
    '</table></div>'+
    (stale ? '<div style="font-size:11px;color:var(--pen);margin-top:4px">Controls were run at '+DB.stateCtl.at+
      ' logged days; the log has moved. Re-run controls to refresh the two right columns.</div>'
    : (!ctl ? '<div style="font-size:11px;color:var(--ink-soft);margin-top:4px">Controls not run yet for this day count &mdash; '+
      'the two right columns fill in when you press Run controls.</div>' : ''));

  /* per-state table, combined across families */
  const rows = Object.entries(m.byState||{})
    .map(([c,s])=>({c,s})).sort((a,b)=>b.s.exp-a.s.exp);
  perEl.innerHTML =
    '<div class="sub-h">Per state &mdash; all families combined</div>'+
    '<div style="overflow-x:auto"><table class="tbl"><tr><th>state</th><th>scored</th><th>draws logged</th>'+
    '<th>hits</th><th>chance</th><th>lift</th></tr>'+
    rows.map(r=>'<tr'+(r.s.exp<MIN?' style="opacity:.55"':'')+'><td>'+nm(r.c)+'</td><td>'+r.s.n+'</td>'+
      '<td>'+((DB.byState[r.c]||[]).length)+'</td><td>'+r.s.hits+'</td><td>'+r.s.exp.toFixed(1)+'</td>'+
      '<td>'+stLift(r.s.hits,r.s.exp,MIN)+'</td></tr>').join('')+
    '</table></div>';

  baseEl.innerHTML =
    '<b>How to read this.</b> A signal fires in a state (one day of that state&rsquo;s own draws run through a book, '+
    'the rules, or the series table) and is scored only against <i>that state&rsquo;s</i> draws the next logged day, '+
    'against the target set&rsquo;s exact field coverage. <b>Same-state</b> is the number this view exists for; '+
    '<b>cross-state</b> is the identical signal scored against every other state &mdash; the pooled behaviour the rest '+
    'of the dashboard already measured at chance. If the books know anything about states, same-state beats cross-state '+
    '(&Delta; &gt; 0) and holds there. <b>Controls:</b> shuffle &ge; is the share of 200 runs with next-day results handed '+
    'to random states that matched or beat the real &Delta; &mdash; near 50% means state identity carries no information; '+
    'random &ge; is the share of 200 randomly generated book sets that matched or beat the real same-state lift. '+
    '<b>Thin data is the rule here:</b> one state gives 1&ndash;4 draws a day (8 states draw only once), so per-state rows '+
    'stay dim until their chance column passes '+MIN+'. With 8 families and ~40 states, a few cells will run hot on luck '+
    'alone &mdash; nothing is a signal unless the aggregate row moves AND both controls come back low. Pooled testing '+
    'across 665 draws came back at chance everywhere, so expect same-state &asymp; cross-state &asymp; 1.00; this panel&rsquo;s '+
    'job is to measure that honestly, not to find a pattern by staring harder.';
}

/* ══════════ STATE SPECIFIC NUMBERS ══════════
   Inverts the state view. The state view asks "what does THIS state need?";
   this panel runs every state through the same four books and groups the
   still-open targets by number, so it answers "which states need 889?" in one
   look. Same window, same books, same open/came rule as the state view, so the
   two panels can never disagree.
   The forward test below scores exactly what the panel shows: at every logged
   day, the numbers each state was pointing at (with the current window), scored
   on that state's NEXT logged day, tiered by how many states agreed. */
function stateTargets(S, win, bk){
  bk = bk || realBooks();
  const evs=[];
  win.forEach((day,i)=>{ const ago=win.length-1-i;
    (day.dayStates[S]||[]).forEach(n=>evs.push({n,ago})); });
  const boxIn={}; evs.forEach(e=>{ const k=sortD(e.n);
    if(boxIn[k]===undefined || e.ago<boxIn[k]) boxIn[k]=e.ago; });
  const T={};
  const addT=(t,book,e)=>{ if(!t) return; const k=sortD(t);
    const o=(T[k]=T[k]||{books:new Set(),ago:e.ago,from:new Set()});
    o.books.add(book); o.from.add(e.n); if(e.ago<o.ago) o.ago=e.ago; };
  evs.forEach(e=>{
    (bk.A16[e.n]||[]).forEach(t=>addT(t,"'16",e));
    (bk.A17[e.n]||[]).forEach(t=>addT(t,"'17",e));
    addT(bk.FU[e.n],'FU',e);
    addT(bk.REL[sortD(e.n)],'REL',e);
    if(use25() && bk.A25) (bk.A25[e.n]||[]).forEach(t=>addT(t,"'25",e));
    if(useRS() && bk.RS) (bk.RS[sortD(e.n)]||[]).forEach(t=>addT(t,'RS',e));
  });
  const open={}, came={};
  Object.entries(T).forEach(([k,o])=>{
    const hitAgo=boxIn[k];
    if(hitAgo!==undefined && hitAgo<=o.ago) came[k]=o; else open[k]=o;
  });
  return {evs, open, came, boxIn};
}

/* number → { stateCode → target info } for every state in the window */
/* Regions — a filter for the list and a scope for the forward test. Pooling
   states into one super-state would throw away per-state scoring, so a region
   here is just a set of states that are looked at together. */
const REGIONS={
  south:{ name:'South', codes:['ar','fl','ga','ky','la','ms','nc','sc','tn','tx','va','wv','ok'] },
  east:{ name:'East', codes:['ct','de','dc','md','nj','ny','pa','xx'] },
  north:{ name:'North', codes:['ia','il','in','ks','mi','mn','mo','ne','oh','wi','on','qc','wc'] },
  west:{ name:'West', codes:['az','ca','co','id','nm','wa'] },
  caribbean:{ name:'Caribbean', codes:['cr','pr'] }
};
function snRegion(){ const el=document.getElementById('snRegion'); const r=el&&el.value;
  return REGIONS[r] ? { id:r, name:REGIONS[r].name, set:new Set(REGIONS[r].codes) } : null; }
function stateNumbersMap(win, bk, reg){
  const states=new Set(); win.forEach(d=>Object.keys(d.dayStates).forEach(c=>{ if(!reg||reg.has(c)) states.add(c); }));
  const G={}, C={};
  states.forEach(S=>{
    const st=stateTargets(S,win,bk);
    Object.entries(st.open).forEach(([k,o])=>{ (G[k]=G[k]||{})[S]=o; });
    Object.entries(st.came).forEach(([k,o])=>{ (C[k]=C[k]||{})[S]=o; });
  });
  return {open:G, came:C, states:[...states]};
}

const SN_TIERS=[
  {id:'t1',name:'1 state',min:1,max:1},
  {id:'t2',name:'2 states',min:2,max:2},
  {id:'t3',name:'3&ndash;4 states',min:3,max:4},
  {id:'t5',name:'5+ states',min:5,max:999},
  {id:'m2',name:'<b>2+ states</b>',min:2,max:999},
  {id:'all',name:'<b>All</b>',min:1,max:999}
];

/* Precompute per transition: for every pointed-at number, which next-day
   states were pointing (pt), the binary hit per state (h) and the chance of at
   least one boxed hit given that state's draw count (exp = 1-(1-p)^n). */
function stateNumbersPre(K, bk, reg){
  const v=DB.dayLog.filter(e=>e.dayStates);
  const pre=[];
  for(let d=0; d<v.length-1; d++){
    const win=v.slice(Math.max(0,d-K+1), d+1);
    const G=stateNumbersMap(win, bk, reg).open;
    const next=v[d+1].dayStates, codes=Object.keys(next).filter(c=>!reg||reg.has(c));
    const nb=codes.map(c=>new Set(next[c].map(sortD)));
    const nD=codes.map(c=>next[c].length);
    const ents=[];
    Object.entries(G).forEach(([k,sts])=>{
      const p=(PERM_COUNT[k]||0)/1000;
      const h=nb.map(s=>s.has(k)?1:0);
      const exp=nD.map(n=>1-Math.pow(1-p,n));
      const pt=Object.keys(sts).map(c=>codes.indexOf(c)).filter(i=>i>=0);
      ents.push({ k:Object.keys(sts).length, h, exp, pt,
        totH:h.reduce((a,b)=>a+b,0), totE:exp.reduce((a,b)=>a+b,0) });
    });
    pre.push({codes, ents});
  }
  return pre;
}

function scoreSN(pre, permute){
  const z=()=>({n:0,plays:0,hits:0,exp:0,oh:0,oe:0});
  const T={}; SN_TIERS.forEach(t=>T[t.id]=z());
  pre.forEach(tr=>{
    const map=permute?shuffleArr(tr.codes.map((_,i)=>i)):null;
    tr.ents.forEach(e=>{
      let sh=0,se=0;
      e.pt.forEach(i=>{ const j=map?map[i]:i; sh+=e.h[j]; se+=e.exp[j]; });
      SN_TIERS.forEach(t=>{ if(e.k>=t.min && e.k<=t.max){ const o=T[t.id];
        o.n++; o.plays+=e.pt.length; o.hits+=sh; o.exp+=se;
        o.oh+=e.totH-sh; o.oe+=e.totE-se; }});
    });
  });
  return T;
}
const snDelta = o => (o.exp>0 && o.oe>0) ? o.hits/o.exp - o.oh/o.oe : null;

let SN_CACHE=null;
function stateNumbersTest(K){
  const v=DB.dayLog.filter(e=>e.dayStates);
  const reg=snRegion();
  const key=v.length+'|'+K+'|'+(reg?reg.id:'all')+'|'+(use25()?'25':'')+(useRS()?'rs':'')+'|'+v.map(e=>e.sig||'').join(',');
  if(SN_CACHE && SN_CACHE.key===key) return SN_CACHE;
  const pre=stateNumbersPre(K, null, reg&&reg.set);
  const real=scoreSN(pre,false);
  const beat={}, cnt={};
  SN_TIERS.forEach(t=>{ beat[t.id]=0; cnt[t.id]=0; });
  for(let r=0;r<200;r++){
    const s=scoreSN(pre,true);
    SN_TIERS.forEach(t=>{ const rd=snDelta(real[t.id]), sd=snDelta(s[t.id]);
      if(rd===null||sd===null) return; cnt[t.id]++; if(sd>=rd) beat[t.id]++; });
  }
  const perm={}; SN_TIERS.forEach(t=>perm[t.id]=cnt[t.id]?Math.round(100*beat[t.id]/cnt[t.id]):null);
  SN_CACHE={key, real, perm, trans:pre.length};
  return SN_CACHE;
}

/* Random-book control for this panel: 100 random four-book sets of identical
   shape run through the very same grouping; share whose lift in the pointing
   states matches or beats the real one, per tier. */
function runSnControl(){
  const st=document.getElementById('snCtlStatus');
  const v=DB.dayLog.filter(e=>e.dayStates);
  if(v.length<2){ st.className='status warn'; st.textContent='needs at least 2 logged days'; return; }
  const K=lookback(), RUNS=100, reg=snRegion();
  const real=stateNumbersTest(K).real;
  const r3=()=>String(Math.floor(Math.random()*1000)).padStart(3,'0');
  const beat={}, cnt={}; SN_TIERS.forEach(t=>{ beat[t.id]=0; cnt[t.id]=0; });
  let done=0;
  st.className='status'; st.textContent='random books 0/'+RUNS+'…';
  const step=()=>{
    for(let b=0;b<4 && done<RUNS;b++,done++){
      const A={},B={},F={},R={},C={};
      for(let i=0;i<1000;i++){ const k=String(i).padStart(3,'0');
        A[k]=[r3(),r3()]; B[k]=[r3(),r3()]; F[k]=r3(); C[k]=[r3(),r3()]; }
      Object.keys(RELATIVES).forEach(k=>{ R[k]=r3(); });
      const S={}; Object.entries(BOLD_REL).forEach(([k,l])=>{ S[k]=l.map(()=>r3()); });
      const s=scoreSN(stateNumbersPre(K,{A16:A,A17:B,FU:F,REL:R,A25:C,RS:S}, reg&&reg.set),false);
      SN_TIERS.forEach(t=>{ const a=real[t.id], b2=s[t.id];
        if(a.exp<=0||b2.exp<=0) return; cnt[t.id]++; if(b2.hits/b2.exp>=a.hits/a.exp) beat[t.id]++; });
    }
    if(done<RUNS){ st.textContent='random books '+done+'/'+RUNS+'…'; setTimeout(step,10); return; }
    const rand={}; SN_TIERS.forEach(t=>rand[t.id]=cnt[t.id]?Math.round(100*beat[t.id]/cnt[t.id]):null);
    DB.snCtl={at:DB.dayLog.length, K, reg:reg?reg.id:'all', b25:use25(), brs:useRS(), rand};
    save(); st.textContent=''; render();
  };
  setTimeout(step,30);
}

function snStateChip(c,o,came){
  if(came) return '<span class="chip gone" title="came in '+nm(c)+' after being pointed at (from '+[...o.from].join(', ')+')">'+
    nm(c)+' &#10005;</span>';
  return '<span class="chip'+(o.books.size>1?' due':'')+'" title="from '+[...o.from].join(', ')+' via '+[...o.books].join(', ')+'">'+
    nm(c)+(o.books.size>1?'<span class="ago">&times;'+o.books.size+'</span>':'')+'</span>';
}
const snHeat = sts => Object.values(sts).reduce((a,o)=>a+o.from.size,0);

/* The rule of thumb itself, tested without any book: a number drawn in one
   state of the region, then boxed in ANOTHER state of the region within 1 and
   3 days, vs the same number travelling to a state outside the region — each
   against the exact chance for the receiving state's draw count. */
let RR_CACHE={};
function regionRepeatHTML(reg){
  const v=DB.dayLog.filter(e=>e.dayStates);
  const key=reg.id+'|'+v.length+'|'+v.map(e=>e.sig||'').join(',');
  if(RR_CACHE.key!==key){
    const res={};
    [1,3].forEach(H=>{
      const same={h:0,e:0}, out={h:0,e:0};
      for(let d=0; d<v.length-1; d++){
        const nb={}, nn={};
        for(let h=1;h<=H&&d+h<v.length;h++) Object.entries(v[d+h].dayStates).forEach(([c,ds])=>{
          (nb[c]=nb[c]||new Set()); ds.forEach(x=>nb[c].add(sortD(x))); nn[c]=(nn[c]||0)+ds.length; });
        Object.entries(v[d].dayStates).forEach(([A,draws])=>{
          if(!reg.set.has(A)) return;
          const seen=new Set();
          draws.forEach(n=>{ const k=sortD(n); if(seen.has(k)) return; seen.add(k);
            const p=(PERM_COUNT[k]||0)/1000;
            Object.keys(nb).forEach(B=>{ if(B===A) return;
              const o=reg.set.has(B)?same:out; o.h+=nb[B].has(k)?1:0; o.e+=1-Math.pow(1-p,nn[B]); });
          });
        });
      }
      res[H]={same,out};
    });
    RR_CACHE={key,res};
  }
  const r=RR_CACHE.res, f=o=>o.h+' vs '+o.e.toFixed(1)+' = <b>'+(o.e?(o.h/o.e).toFixed(2):'&mdash;')+'</b>';
  return '<div class="sub-h">Do '+reg.name+' states play together? (no books &mdash; a number drawn in one '+reg.name+
    ' state, then boxed in another)</div>'+
    '<div style="overflow-x:auto"><table class="tbl"><tr><th>horizon</th><th>to another '+reg.name+' state</th><th>to a state outside '+reg.name+'</th></tr>'+
    '<tr><td>next day</td><td>'+f(r[1].same)+'</td><td>'+f(r[1].out)+'</td></tr>'+
    '<tr><td>within 3 days</td><td>'+f(r[3].same)+'</td><td>'+f(r[3].out)+'</td></tr></table></div>'+
    '<div style="font-size:11px;color:var(--ink-soft);margin-top:4px">If the region plays together, the left column beats the right and stays there as days are added. '+
    'Measured Sept 6&ndash;28: South 0.99 vs 1.06 next day, 1.01 vs 1.02 within 3 days &mdash; a hot number travelled to another Southern state exactly as often as anywhere else. Agreement among Southern states scored 0.88 in the 2+ tier (19 hits vs 21.6).</div>';
}

/* Plain book lookup for one number: what each book says it brings, and which
   numbers bring IT. Every book, ticked or not — this is a reference, not a
   signal, so nothing here depends on the checkboxes. Straight-keyed books
   ('16, '17, Follow Ups, Grandma 2025) are read at the typed arrangement;
   Relative Numbers and Red Side are boxed. Each relative carries how long ago
   it last landed anywhere in the log. */
let REV_CACHE=null;
function bookReverse(){
  if(REV_CACHE) return REV_CACHE;
  const fu={}, rel={}, rs={};
  Object.entries(FOLLOWUPS).forEach(([k,t])=>{ (fu[t]=fu[t]||[]).push(k); });
  Object.entries(RELATIVES).forEach(([k,t])=>{ (rel[sortD(t)]=rel[sortD(t)]||[]).push(k); });
  Object.entries(BOLD_REL).forEach(([k,l])=>l.forEach(t=>{ (rs[sortD(t)]=rs[sortD(t)]||[]).push(k); }));
  return REV_CACHE={fu,rel,rs};
}
function bookLookupHTML(q){
  const k=sortD(q), rv=bookReverse();
  const chip=n=>{ const L=lastLanded(n);
    return '<span class="chip" style="padding:2px 6px" title="'+(L?'last landed '+agoTxt(L.ago)+' ('+L.states.join(', ')+')':'not in the log')+'">'+n+
      '<span class="ago">'+(L?(L.ago===0?'today':L.ago+'d'):'&mdash;')+'</span></span>'; };
  const row=(name,list,note)=>'<tr><td style="white-space:nowrap">'+name+(note?' <span style="color:var(--ink-soft);font-size:10px">'+note+'</span>':'')+'</td>'+
    '<td>'+(list&&list.length?list.map(chip).join(''):'<span style="color:var(--ink-soft)">&mdash;</span>')+'</td></tr>';
  const uniq=a=>[...new Set(a||[])];
  const brings=[
    row("Almanac &rsquo;16", ALMANAC[q], 'straight'),
    row("Almanac &rsquo;17", ALMANAC17[q], 'straight'),
    row('Follow Ups', FOLLOWUPS[q]?[FOLLOWUPS[q]]:[], 'straight'),
    row('Relative Numbers', RELATIVES[k]?[RELATIVES[k]]:[], 'boxed'),
    row('Grandma 2025', ALMANAC25[q], 'straight'),
    row('Red Side', BOLD_REL[k], 'boxed') ].join('');
  const broughtBy=[
    row("Almanac &rsquo;16", uniq(REVERSE[q]), 'straight'),
    row("Almanac &rsquo;17", uniq(REVERSE17[q]), 'straight'),
    row('Follow Ups', uniq(rv.fu[q]), 'straight'),
    row('Relative Numbers', uniq(rv.rel[k]), 'boxed'),
    row('Grandma 2025', uniq(REVERSE25[q]), 'straight'),
    row('Red Side', uniq(rv.rs[k]), 'boxed') ].join('');
  return '<div class="sub-h">What the books say '+q+' brings</div>'+
    '<div style="overflow-x:auto"><table class="tbl">'+brings+'</table></div>'+
    '<div class="sub-h">What brings '+q+' (numbers whose row lists it)</div>'+
    '<div style="overflow-x:auto"><table class="tbl">'+broughtBy+'</table></div>'+
    '<div style="font-size:11px;color:var(--ink-soft);margin-top:4px">Reference only &mdash; every book is shown whether or not it is ticked. '+
    'The small tag is how long since that number last landed anywhere in your log (&mdash; = never). '+
    'Straight books are read at the arrangement you typed; try the other arrangements for their own rows.</div>';
}

function renderStateNumbers(){
  const cntEl=document.getElementById('snCount');
  const lkEl=document.getElementById('snLookupOut');
  const listEl=document.getElementById('snList');
  const scEl=document.getElementById('snScore');
  const baseEl=document.getElementById('snBase');
  const v=DB.dayLog.filter(e=>e.dayStates);
  if(!v.length){ cntEl.textContent=''; lkEl.innerHTML=''; scEl.innerHTML=''; baseEl.innerHTML='';
    listEl.innerHTML='<div class="empty">Add a day to begin.</div>'; return; }
  const K=lookback(), reg=snRegion();
  const win=v.slice(-K);
  const M=stateNumbersMap(win, null, reg&&reg.set);
  const minS=parseInt(document.getElementById('snMin').value,10)||1;
  const rows=Object.entries(M.open).map(([k,sts])=>({k,sts,n:Object.keys(sts).length,heat:snHeat(sts),came:M.came[k]||{}}))
    .sort((a,b)=>b.n-a.n || b.heat-a.heat || (a.k<b.k?-1:1));
  const multi=rows.filter(r=>r.n>=2).length;
  cntEl.textContent=(reg?reg.name+' · ':'')+rows.length+' numbers open · '+multi+' wanted by 2+ states · '+win.length+'-day window'+(use25()?' · incl. Grandma 2025':'')+(useRS()?' · incl. Red Side':'');

  /* per-state draws per day in the window, for the chance line */
  const dpd={}; M.states.forEach(S=>{ let n=0; win.forEach(d=>n+=(d.dayStates[S]||[]).length); dpd[S]=n/win.length; });

  /* lookup */
  const q=(document.getElementById('snLookup').value||'').replace(/\D/g,'');
  if(q.length===3){
    const k=sortD(q), sts=M.open[k]||{}, came=M.came[k]||{};
    const pt=Object.keys(sts).sort((a,b)=>sts[b].books.size-sts[a].books.size||(nm(a)<nm(b)?-1:1));
    const p=(PERM_COUNT[k]||0)/1000;
    let chance3=1; pt.forEach(S=>{ chance3*=Math.pow(1-p, 3*dpd[S]); }); chance3=1-chance3;
    const landed=[]; v.slice(-K).forEach((d,i)=>{ const ago=win.length-1-i;
      Object.entries(d.dayStates).forEach(([c,ds])=>{ if(ds.some(x=>sortD(x)===k)) landed.push(nm(c)+' '+agoTxt(ago)); }); });
    lkEl.innerHTML='<div class="sub-h" style="margin-top:0">Which states need '+q+(k!==q?' (boxed '+k+')':'')+'</div>'+
      (pt.length||Object.keys(came).length ? '<div>'+pt.map(c=>snStateChip(c,sts[c])).join('')+
          Object.keys(came).sort().map(c=>snStateChip(c,came[c],true)).join('')+'</div>'+
          (pt.length ? '<div style="font-size:11px;color:var(--ink-soft)">still open in '+pt.length+' state'+(pt.length>1?'s':'')+
            ' &middot; heat '+snHeat(sts)+' (trigger draws pointing at it across those states)'+
            (Object.keys(came).length?' &middot; &#10005; = came there already; the other states stay listed':'')+'</div>' : '') :
        '<div class="empty" style="font-size:12px">no state is pointing at '+k+' in this window.</div>')+
      (landed.length ? '<div style="font-size:11px;color:var(--ink-soft)">landed in window: '+landed.join(', ')+'</div>' : '')+
      (pt.length ? '<div style="font-size:11px;color:var(--pen);margin-top:4px">chance '+k+' lands boxed in at least one of these '+pt.length+
        ' state'+(pt.length>1?'s':'')+' within 3 days on their schedules: <b>'+(100*chance3).toFixed(0)+'%</b> '+
        '('+(PERM_COUNT[k]||0)+'/1000 per draw) &mdash; that is the bar a hit has to beat.</div>' : '')+
      '<div style="font-size:11px;color:var(--ink-soft);margin-top:4px">For what every book says '+q+' brings, and what brings it, use <b>Lookup a number</b> below.</div>';
  } else lkEl.innerHTML=q.length?'<div class="empty" style="font-size:12px">type all three digits.</div>':'';

  /* the grouped list */
  const shown=rows.filter(r=>r.n>=minS);
  listEl.innerHTML='<div class="sub-h">Numbers wanted by '+minS+'+ state'+(minS>1?'s':'')+' &mdash; open in every state listed</div>'+
    (shown.length ? capList(shown,'snList',30,r=>{
      const cs=Object.keys(r.sts).sort((a,b)=>r.sts[b].books.size-r.sts[a].books.size||(nm(a)<nm(b)?-1:1));
      return '<div style="display:flex;gap:6px;align-items:flex-start;padding:3px 0;border-bottom:1px dotted var(--rule)">'+
        '<span class="chip" style="font-weight:700;min-width:44px;text-align:center;cursor:pointer" onclick="openLookup(\''+r.k+'\')" title="open '+r.k+' in Lookup a number">'+r.k+'</span>'+
        '<span style="font-family:\'Roboto Mono\',monospace;font-size:11px;color:var(--ink-soft);padding-top:5px;min-width:64px" title="states still needing it · heat = trigger draws pointing at it">&times;'+r.n+' &middot; h'+r.heat+'</span>'+
        '<span style="flex:1">'+cs.map(c=>snStateChip(c,r.sts[c])).join('')+
          Object.keys(r.came).sort().map(c=>snStateChip(c,r.came[c],true)).join('')+'</span></div>'; })
    : '<div class="empty" style="font-size:12px">no number is wanted by '+minS+'+ states in this window.</div>');

  /* forward test */
  if(v.length<2){ scEl.innerHTML=''; baseEl.innerHTML=''; return; }
  const T=stateNumbersTest(K);
  const ctl=(DB.snCtl && DB.snCtl.at===DB.dayLog.length && DB.snCtl.K===K && (DB.snCtl.reg||'all')===(reg?reg.id:'all') && !!DB.snCtl.b25===use25() && !!DB.snCtl.brs===useRS()) ? DB.snCtl : null;
  const stale=DB.snCtl && !ctl;
  const MIN=5;
  scEl.innerHTML='<div class="sub-h">Forward test &mdash; does agreement across '+(reg?reg.name+' states':'states')+' predict those states? ('+T.trans+' transitions, '+K+'-day window)</div>'+
    '<div style="overflow-x:auto"><table class="tbl"><tr><th>agreement</th><th>numbers</th><th>plays</th><th>hits</th><th>chance</th>'+
    '<th>hit rate</th><th>in pointing states</th><th>in other states</th><th>&Delta;</th>'+
    '<th title="share of 200 label shuffles matching or beating the real Δ">shuffle &ge;</th>'+
    '<th title="share of 100 random book sets matching or beating the real pointing-state lift">random &ge;</th></tr>'+
    SN_TIERS.map(t=>{ const o=T.real[t.id], d=snDelta(o);
      return '<tr'+(t.id==='m2'?' style="border-top:2px solid var(--rule)"':'')+'><td>'+t.name+'</td><td>'+o.n+'</td><td>'+o.plays+'</td>'+
        '<td>'+o.hits+'</td><td>'+o.exp.toFixed(1)+'</td>'+
        '<td>'+(o.plays?(100*o.hits/o.plays).toFixed(1)+'% vs '+(100*o.exp/o.plays).toFixed(1)+'%':'&mdash;')+'</td>'+
        '<td>'+stLift(o.hits,o.exp,MIN)+'</td><td>'+stLift(o.oh,o.oe,MIN)+'</td>'+
        '<td>'+(d===null?'&mdash;':'<b style="color:'+(d>0?'#1D6B3F':'var(--pen)')+'">'+(d>0?'+':'')+d.toFixed(2)+'</b>')+'</td>'+
        '<td>'+(T.perm[t.id]===null?'&mdash;':T.perm[t.id]+'%')+'</td>'+
        '<td>'+(ctl&&ctl.rand[t.id]!==null&&ctl.rand[t.id]!==undefined?ctl.rand[t.id]+'%':'&mdash;')+'</td></tr>'; }).join('')+
    '</table></div>'+
    (stale ? '<div style="font-size:11px;color:var(--pen);margin-top:4px">Random-book control was run at '+DB.snCtl.at+' days / '+DB.snCtl.K+'-day window; re-run it for this view.</div>'
      : (!ctl ? '<div style="font-size:11px;color:var(--ink-soft);margin-top:4px">Random-book control not run yet for this day count and window.</div>' : ''))+
    (reg ? regionRepeatHTML(reg) : '');

  baseEl.innerHTML='<b>How to read this.</b> Every state&rsquo;s own draws in the window are run through the four books exactly as '+
    'the state view does; a number is listed under a state while it is still open there (pointed at and not yet landed in that state '+
    'since). The list groups those by number, so &times;6 means six states are currently pointing at it. '+
    '<b>The test above scores what this list showed on every earlier day:</b> each (number, state) pair is one play, scored on that '+
    'state&rsquo;s next logged day as a boxed hit, against the chance of at least one hit given that state&rsquo;s draw count '+
    '(1&minus;(1&minus;p)<sup>n</sup>). <b>In pointing states</b> is the lift the panel is claiming; <b>in other states</b> is the same '+
    'number scored in the states that were <i>not</i> pointing at it &mdash; if agreement means anything, the first beats the second '+
    'and shuffle &ge; sits well under 50%. <b>The trap in this view:</b> a number six states &ldquo;need&rdquo; has six chances to land, '+
    'so it will land in one of them fairly often by arithmetic alone &mdash; a boxed double at 3/1000 per draw across six two-draw states '+
    'is about 10% over three days, a boxed 6-way number about 20%. Seeing it come in one of the six is the expected outcome, not '+
    'confirmation. Only the lift column, on plays actually made, says whether narrowing to pointing states buys anything. '+
    '<b>Crossed-off states and heat:</b> when a number lands in one of the states calling it, that state is shown crossed out and the '+
    'number stays listed for the rest; <i>heat</i> counts the trigger draws pointing at it across those states. Both were tested on '+
    'Sept 6&ndash;28: after a number fell in one calling state, the remaining callers hit 9 times vs 6.5 expected over the next two days '+
    '(too few to mean anything either way), and numbers with more triggers behind them did not come in more often (1 trigger 1.04, '+
    '2 triggers 1.12 on 8 hits; 2+ books 0.79). Heat is a sort order, not a forecast.';
}

/* ══════════ BACKFILL DATES ══════════
   Days logged before dates were recorded carry none. They were added one per
   calendar day, so they can be dated by counting backward — and the result is
   checkable: this feed posts no Texas or West Virginia Pick 3 on Sundays, so
   the days missing Texas must land on Sundays. The preview reports that match
   before anything is written. */
const DAYNAMES=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
function isoAdd(iso, k){ const d=new Date(iso+'T12:00:00'); d.setDate(d.getDate()+k);
  return d.getFullYear()+'-'+pad2(d.getMonth()+1)+'-'+pad2(d.getDate()); }
function dowOf(iso){ return new Date(iso+'T12:00:00').getDay(); }
function undatedIdx(){ const o=[];
  (DB.dayLog||[]).forEach((d,i)=>{ if(!d.date) o.push(i); }); return o; }
/* Rather than guess, find the end date that actually fits: slide the whole run
   back a day at a time and keep the alignment that puts every Texas-less day on
   a Sunday. The naive guess (counting straight back from today) assumes you
   logged without ever missing or doubling a day, which is rarely true. */
function suggestEnd(){
  const log=DB.dayLog||[], u=undatedIdx();
  if(!u.length) return todayISO();
  const firstDated = log.find(d=>d.date);
  const naive = firstDated
    ? isoAdd(firstDated.date, -(log.findIndex(d=>d.date) - u[u.length-1]))
    : isoAdd(todayISO(), -(log.length-1-u[u.length-1]));
  let best=naive, bestScore=-1;
  for(let shift=0; shift>=-13; shift--){
    const cand=isoAdd(naive, shift);
    const c=sundayCheck(planDates(cand));
    if(c.agree>bestScore){ bestScore=c.agree; best=cand; }
    if(c.agree===c.total) return cand;       // exact fit, stop here
  }
  return best;
}
function planDates(endStr){
  const u=undatedIdx(); if(!u.length) return [];
  return u.map((idx,k)=>({ idx, date: isoAdd(endStr, -(u.length-1-k)) }));
}
/* Sunday check: a day with no Texas draws should be a Sunday, and vice versa. */
function sundayCheck(plan){
  let agree=0, sundays=0, noTx=0, conflicts=[];
  plan.forEach(p=>{
    const ds=DB.dayLog[p.idx].dayStates||{};
    const hasTx=!!ds.tx, sun=dowOf(p.date)===0;
    if(sun) sundays++;
    if(!hasTx) noTx++;
    if(sun === !hasTx) agree++; else conflicts.push('day '+(p.idx+1)+' → '+p.date+' ('+DAYNAMES[dowOf(p.date)]+', Texas '+(hasTx?'present':'absent')+')');
  });
  return {agree, total:plan.length, sundays, noTx, conflicts};
}
function previewDates(){
  const st=document.getElementById('bfStatus'), out=document.getElementById('bfOut');
  const plan=planDates(document.getElementById('bfDate').value || suggestEnd());
  if(!plan.length){ st.className='status ok'; st.textContent='every logged day already has a date';
    out.innerHTML=''; return; }
  const c=sundayCheck(plan);
  st.className='status'; st.textContent=plan.length+' days to date';
  out.innerHTML =
    '<b>Preview &mdash; nothing written yet.</b> Day '+(plan[0].idx+1)+' &rarr; <b>'+plan[0].date+'</b> ('+
    DAYNAMES[dowOf(plan[0].date)]+') &hellip; day '+(plan[plan.length-1].idx+1)+' &rarr; <b>'+
    plan[plan.length-1].date+'</b> ('+DAYNAMES[dowOf(plan[plan.length-1].date)]+'), one calendar day each.'+
    '<br><b>Alignment check:</b> this feed posts no Texas Pick 3 on Sundays. '+
    'Under these dates '+c.agree+' of '+c.total+' days agree ('+c.sundays+' land on a Sunday, '+
    c.noTx+' have no Texas draw)'+
    (c.agree===c.total
      ? ' &mdash; <b style="color:#1D6B3F">a clean match, the dates line up</b>.'
      : ' &mdash; <b style="color:var(--pen)">'+c.conflicts.length+' disagree</b>, so the end date is probably off by a day or two. '+
        'Shift it and preview again before applying.<br>'+c.conflicts.slice(0,6).join('<br>'));
}
function applyDates(){
  const st=document.getElementById('bfStatus');
  const endStr=document.getElementById('bfDate').value || suggestEnd();
  const plan=planDates(endStr);
  if(!plan.length){ st.className='status ok'; st.textContent='nothing to date'; return; }
  const c=sundayCheck(plan);
  if(!armed('applydates','Dating '+plan.length+' days, ending '+plan[plan.length-1].date+
      ' — '+c.agree+' of '+c.total+' agree with the Sunday pattern. Press Apply again to write it.')) return;
  plan.forEach(p=>{ DB.dayLog[p.idx].date=p.date; });
  save();
  st.className='status ok'; st.textContent='dated '+plan.length+' days';
  render();
}

